'use client';

import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
    ProductDashedSurface,
    ProductDialogFooter,
    ProductDialogFormLabel,
    productDialogBodyClass,
    productDialogOutlineButtonClass,
    productDialogPrimaryButtonClass,
    productDialogSectionHeadingClass,
} from '@/design-system';
import { LoaderCircle, Plus, Save, Trash2 } from 'lucide-react';
import type { CertidaoPadraoTemplate } from '@/components/certidoes-padrao/types';

export interface ICreateViewProps {
    padraoDraft: CertidaoPadraoTemplate;
    onUpdateDraft: (data: Partial<CertidaoPadraoTemplate>) => void;
    onAddCertidao: (tipo: 'fiscal' | 'processual') => void;
    onRemoveCertidao: (index: number) => void;
    onSave: () => void;
    onUpdate: () => void;
    onDelete: (id: number) => void;
    isSaving?: boolean;
    isUpdating?: boolean;
    isDeleting?: boolean;
    isEditing?: boolean;
}

function CertidaoDraftList({
    items,
    padraoDraft,
    onUpdateDraft,
    onRemoveCertidao,
    isPending,
    emptyLabel,
}: {
    items: { index: number; name: string }[];
    padraoDraft: CertidaoPadraoTemplate;
    onUpdateDraft: (data: Partial<CertidaoPadraoTemplate>) => void;
    onRemoveCertidao: (index: number) => void;
    isPending: boolean;
    emptyLabel: string;
}) {
    if (items.length === 0) {
        return <ProductDashedSurface className="py-6 text-xs">{emptyLabel}</ProductDashedSurface>;
    }

    return (
        <div className="flex flex-col gap-2">
            {items.map(({ index, name }) => (
                <div key={index} className="flex items-center gap-2">
                    <Input
                        value={name}
                        placeholder="Nome da certidão"
                        className="h-9 text-sm"
                        onChange={(e) => {
                            const newData = [...padraoDraft.data];
                            newData[index] = { ...newData[index], name: e.target.value };
                            onUpdateDraft({ data: newData });
                        }}
                        disabled={isPending}
                    />
                    <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="h-9 w-9 shrink-0 text-destructive hover:bg-destructive/10 hover:text-destructive"
                        onClick={() => onRemoveCertidao(index)}
                        disabled={isPending}
                        aria-label="Remover certidão"
                    >
                        <Trash2 size={14} aria-hidden />
                    </Button>
                </div>
            ))}
        </div>
    );
}

export function CreateView({
    padraoDraft,
    onUpdateDraft,
    onAddCertidao,
    onRemoveCertidao,
    onSave,
    onUpdate,
    onDelete,
    isSaving,
    isUpdating,
    isDeleting,
    isEditing,
}: ICreateViewProps) {
    const fiscais = padraoDraft.data
        .map((item, index) => ({ item, index }))
        .filter(({ item }) => item.tipo === 'fiscal')
        .map(({ item, index }) => ({ index, name: item.name }));

    const processuais = padraoDraft.data
        .map((item, index) => ({ item, index }))
        .filter(({ item }) => item.tipo === 'processual')
        .map(({ item, index }) => ({ index, name: item.name }));

    const isPending = Boolean(isSaving || isUpdating || isDeleting);

    const canSave =
        fiscais.length > 0 &&
        processuais.length > 0 &&
        padraoDraft.template.trim() !== '' &&
        !isPending;

    return (
        <>
            <div className={productDialogBodyClass}>
                <div className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                    <ProductDialogFormLabel htmlFor="padrao-nome">Nome do padrão</ProductDialogFormLabel>
                    <Input
                        id="padrao-nome"
                        placeholder="Ex.: Padrão básico"
                        className="h-9 text-sm"
                        value={padraoDraft.template}
                        onChange={(e) => onUpdateDraft({ template: e.target.value })}
                        disabled={isPending}
                    />
                </div>

                <section className="space-y-3">
                    <div className="flex items-center justify-between gap-3">
                        <h2 className={productDialogSectionHeadingClass}>Certidões fiscais</h2>
                        <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="h-8 gap-1 rounded-xl text-xs font-semibold"
                            onClick={() => onAddCertidao('fiscal')}
                            disabled={isPending}
                        >
                            <Plus size={12} aria-hidden />
                            Adicionar
                        </Button>
                    </div>
                    <CertidaoDraftList
                        items={fiscais}
                        padraoDraft={padraoDraft}
                        onUpdateDraft={onUpdateDraft}
                        onRemoveCertidao={onRemoveCertidao}
                        isPending={isPending}
                        emptyLabel="Nenhuma certidão fiscal adicionada."
                    />
                </section>

                <section className="space-y-3">
                    <div className="flex items-center justify-between gap-3">
                        <h2 className={productDialogSectionHeadingClass}>Certidões processuais</h2>
                        <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="h-8 gap-1 rounded-xl text-xs font-semibold"
                            onClick={() => onAddCertidao('processual')}
                            disabled={isPending}
                        >
                            <Plus size={12} aria-hidden />
                            Adicionar
                        </Button>
                    </div>
                    <CertidaoDraftList
                        items={processuais}
                        padraoDraft={padraoDraft}
                        onUpdateDraft={onUpdateDraft}
                        onRemoveCertidao={onRemoveCertidao}
                        isPending={isPending}
                        emptyLabel="Nenhuma certidão processual adicionada."
                    />
                </section>
                </div>
            </div>

            <ProductDialogFooter className="sm:justify-end">
                {isEditing ? (
                    <>
                        <JuridicoCommonDialog
                            title="Excluir padrão"
                            description={`Tem certeza de que deseja excluir o padrão "${padraoDraft.template}"?`}
                            confirmButtonText="Excluir"
                            confirmButtonFn={() => onDelete(padraoDraft.id)}
                            trigger={
                                <Button
                                    type="button"
                                    variant="outline-danger"
                                    size="flattened"
                                    className={productDialogOutlineButtonClass}
                                    disabled={isPending}
                                >
                                    {isDeleting ? (
                                        <>
                                            <LoaderCircle size={14} className="animate-spin" aria-hidden />
                                            Excluindo...
                                        </>
                                    ) : (
                                        <>
                                            <Trash2 size={14} aria-hidden />
                                            Excluir padrão
                                        </>
                                    )}
                                </Button>
                            }
                        />
                        <Button
                            type="button"
                            size="flattened"
                            className={productDialogPrimaryButtonClass}
                            disabled={!canSave}
                            onClick={onUpdate}
                        >
                            {isUpdating ? (
                                <>
                                    <LoaderCircle size={14} className="animate-spin" aria-hidden />
                                    Salvando...
                                </>
                            ) : (
                                <>
                                    <Save size={14} aria-hidden />
                                    Salvar edição
                                </>
                            )}
                        </Button>
                    </>
                ) : (
                    <Button
                        type="button"
                        size="flattened"
                        className={productDialogPrimaryButtonClass}
                        disabled={!canSave}
                        onClick={onSave}
                    >
                        {isSaving ? (
                            <>
                                <LoaderCircle size={14} className="animate-spin" aria-hidden />
                                Salvando...
                            </>
                        ) : (
                            <>
                                <Save size={14} aria-hidden />
                                Salvar padrão
                            </>
                        )}
                    </Button>
                )}
            </ProductDialogFooter>
        </>
    );
}

