        isTerceiro && tipoWatch === 'com_repercussao' && poloWatch === 'passivo';
    const contabilizarCedenteDisabled =
        lockedMain || !selectedProc.id || isContabilizandoDivida;
    const isContabilizadoNoCedente = !!(
        selectedProc.id && isProcessoContabilizado(processosContabilizados, String(selectedProc.id))
    );
    const isVinculadoPrecatorio = selectedProc.vinculado_a === 'precatorio';
    const contabilizarCedenteCheckboxId = useId();

