                            name="tipo"
                            render={({ field }) => (
                                <FormItem className="flex flex-col gap-1">
                                    <FormLabel className="text-[0.68rem] font-semibold text-zinc-500 dark:text-zinc-400">
                                        Tipo do Processo
                                    </FormLabel>
                                    <Select
                                        value={field.value ?? 'com_repercussao'}
                                        onValueChange={(v) => onSelectValueChangeGuard(v, field)}
                                        disabled={lockedMain}
                                    >
                                        <FormControl>
                                            <SelectTrigger className={selectTriggerCls}>
                                                <SelectValue />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem
                                                value="com_repercussao"
                                                className={selectItemCls}
                                            >
                                                {tipoLabels.com_repercussao}
                                            </SelectItem>
                                            <SelectItem
                                                value="sem_repercussao"
                                                className={selectItemCls}
                                            >
                                                {tipoLabels.sem_repercussao}
                                            </SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="polo"
