                                        <FormControl>
                                            <SelectTrigger className={selectTriggerCls}>
                                                <SelectValue />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            <SelectItem value="passivo" className={selectItemCls}>
                                                Polo Passivo
                                            </SelectItem>
                                            <SelectItem value="ativo" className={selectItemCls}>
                                                Polo Ativo
                                            </SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="natureza"
                            render={({ field }) => (
                                <FormItem className="flex flex-col gap-1">
                                    <FormLabel className="text-[0.68rem] font-semibold text-zinc-500 dark:text-zinc-400">
                                        Natureza
                                    </FormLabel>
