                                            <SelectTrigger className={selectTriggerCls}>
                                                <SelectValue />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            {FASE_OPTIONS.map((fase) => (
                                                <SelectItem
                                                    key={fase}
