                                message={CONTABILIZAR_CEDENTE_TOOLTIP}
                            >
                                <div
                                    className={cn(
                                        'inline-flex items-center gap-1.5',
                                        contabilizarCedenteDisabled && 'opacity-50',
                                    )}
                                >
                                    <Checkbox
                                        id={contabilizarCedenteCheckboxId}
                                        checked={isContabilizadoNoCedente}
                                        disabled={contabilizarCedenteDisabled}
                                        onCheckedChange={() => vm.handleContabilizarDivida(pessoaId)}
                                    />
                                    <Label
                                        htmlFor={contabilizarCedenteCheckboxId}
                                        className={cn(
                                            'cursor-pointer text-[0.7rem] font-normal leading-snug',
                                            contabilizarCedenteDisabled && 'cursor-not-allowed',
                                        )}
                                    >
                                        Contabilizar dívida deste processo na esfera do cedente
                                    </Label>
                                    {isContabilizandoDivida ? (
                                        <Loader className="size-3 shrink-0 animate-spin text-zinc-500" />
                                    ) : null}
                                </div>
                            </GlobalTooltip>
                        )}
                        {selectedProc.id && (
                            <div className="inline-flex flex-wrap items-center gap-3">
                                <JuridicoCommonDialog
                                    title="Processo do precatório"
                                    description={PRECATORIO_DELETE_DESCRIPTION}
                                    confirmButtonText="Sim, excluir"
                                    cancelButtonText="Cancelar"
                                    confirmButtonFn={onConfirmPrecatorioExclusao}
                                    trigger={
                                        <button
                                            type="button"
                                            disabled={lockedMain}
                                            className={cn(
                                                'inline-flex items-center gap-1.5 rounded-md bg-transparent text-left',
                                                lockedMain && 'opacity-50',
                                            )}
                                        >
                                            <Checkbox
                                                checked={false}
                                                disabled
                                                className="pointer-events-none"
                                                aria-hidden
                                                tabIndex={-1}
                                            />
                                            <span className="cursor-pointer text-[0.7rem] font-normal">
                                                Processo do precatório
                                            </span>
                                        </button>
                                    }
                                />
                                <JuridicoCommonDialog
                                    title="Migrar processo ao precatório"
                                    description={MIGRAR_PRECATARIO_MODAL_DESCRIPTION}
                                    confirmButtonText="Confirmar"
                                    cancelButtonText="Cancelar"
                                    confirmButtonFn={() =>
                                        handleUpdateProcesso(
                                            { vinculado_a: 'precatorio' },
                                            PROCESSO_FORM_LOADING.migrating,
                                        )
                                    }
                                    trigger={
                                        <button
                                            type="button"
                                            disabled={lockedMain || isVinculadoPrecatorio}
                                            className={cn(
                                                'inline-flex items-center gap-1.5 rounded-md bg-transparent text-left',
                                                (lockedMain || isVinculadoPrecatorio) && 'opacity-50',
                                            )}
                                        >
                                            <Checkbox
                                                checked={isVinculadoPrecatorio}
                                                disabled
                                                className="pointer-events-none"
                                                aria-hidden
                                                tabIndex={-1}
                                            />
                                            <span className="cursor-pointer text-[0.7rem] font-normal">
