                                        Litispendência?
                                    </FormLabel>
                                    <FormControl>
                                        <div
                                            role="radiogroup"
                                            aria-label="Litispendência?"
                                            className="relative grid w-fit grid-cols-2 rounded-lg border border-zinc-200 bg-zinc-50 p-0.5 text-[0.7rem] dark:border-zinc-800 dark:bg-zinc-900"
                                        >
                                            <div
                                                className={cn(
                                                    'pointer-events-none absolute inset-y-0.5 left-0.5 w-[calc(50%-0.125rem)] rounded-md border transition-[transform,background-color,border-color] duration-300 ease-out',
