                                {situacaoKey === DueDiligenceProcessosSituacao.ATIVO && (
                                    <button
                                        type="button"
                                        onClick={vm.handleDocumentoClear}
                                        disabled={lockedMain || deleteAutoProcessosMutation.isPending}
                                        className="ml-auto shrink-0 text-zinc-500 hover:text-red-500"
                                    >
                                        {deleteAutoProcessosMutation.isPending ? (
                                            <Loader className="size-2.5 animate-spin" />
                                        ) : (
                                            <X size={10} />
                                        )}
                                    </button>
                                )}
                            </div>
                        ) : (
                            <label
                                className={cn(
                                    'flex cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-dashed border-zinc-300 py-2 text-[0.68rem] font-semibold text-zinc-500 transition-colors hover:border-celer-blue/40 hover:text-celer-blue dark:border-zinc-700 dark:text-zinc-400',
                                    attachZoneMutedCls,
                                    situacaoKey !== DueDiligenceProcessosSituacao.ATIVO && 'opacity-50 pointer-events-none',
                                )}
                            >
                                {isSavingAutosProcessos ? (
                                    <span className="inline-flex items-center gap-1.5">
                                        <Loader className="size-3.5 animate-spin" />
                                        Salvando…
                                    </span>
                                ) : (
                                    <span className="inline-flex items-center gap-1.5">
                                        <Upload size={12} /> Autos Integrais
                                    </span>
                                )}

                                <input
                                    type="file"
                                    className="hidden"
                                    accept={DD_DOCUMENT_FILE_ACCEPT}
                                    disabled={cannotAttachFiles}
                                    onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        e.target.value = '';
                                        if (f) vm.handleUploadAutosProcessos(f);
                                    }}
                                />
                            </label>
                        )}
                        <p className="text-[0.68rem] leading-snug text-zinc-400 dark:text-zinc-500">
                            {DD_DOCUMENT_ALLOWED_HINT}
                        </p>
                    </div>

                    <div className="mt-3 flex flex-col gap-1.5 md:col-span-2">
                        <span className="text-[0.68rem] font-semibold text-zinc-500 dark:text-zinc-400">
                            Outros documentos / folhas específicas
                        </span>
                        {(selectedProc.docs_avulsos?.length ?? 0) > 0 && (
                            <div className="flex flex-col gap-1.5">
                                {(selectedProc.docs_avulsos ?? []).map((doc) => (
                                    <div
                                        key={doc.id}
                                        className="flex items-center gap-1.5 rounded-lg border border-zinc-200 bg-zinc-50 px-2 py-1.5 text-[0.68rem] text-zinc-600 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-300"
                                    >
                                        <button
                                            type="button"
                                            onClick={() => handlePreviewDocumento(doc)}
                                            className="flex min-w-0 flex-1 items-center gap-1.5 text-left hover:text-zinc-800 dark:hover:text-zinc-100"
                                        >
                                            <FileText size={12} className="shrink-0" />
                                            <span className="truncate">{doc.name ?? doc.nome_original}</span>
                                        </button>
                                        {situacaoKey === DueDiligenceProcessosSituacao.ATIVO && (
                                            <button
                                                type="button"
                                                onClick={() => vm.handleDocsAvulsoRemove(doc.id)}
                                                disabled={lockedMain}
                                                className="ml-auto shrink-0 text-zinc-500 hover:text-red-500"
                                            >
                                                <X size={10} />
                                            </button>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                        <label
                            className={cn(
                                'flex cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-dashed border-zinc-300 py-2 text-[0.68rem] font-semibold text-zinc-500 transition-colors hover:border-celer-blue/40 hover:text-celer-blue dark:border-zinc-700 dark:text-zinc-400',
                                attachZoneMutedCls,
                                situacaoKey !== DueDiligenceProcessosSituacao.ATIVO && 'opacity-50 pointer-events-none',
                            )}
                        >
                            {isSavingDocsAvulsos ? (
                                <span className="inline-flex items-center gap-1.5">
                                    <Loader className="size-3.5 animate-spin" />
                                    Enviando…
                                </span>
                            ) : (
                                <span className="inline-flex items-center gap-1.5">
                                    <Plus size={12} /> Adicionar documentos ou folhas específicas
                                </span>
                            )}
                            <input
                                type="file"
                                className="hidden"
                                accept={DD_DOCUMENT_FILE_ACCEPT}
                                disabled={cannotAttachFiles}
                                onChange={(e) => {
                                    const f = e.target.files?.[0];
                                    e.target.value = '';
                                    if (f) vm.handleUploadOtherDocs(f);
                                }}
                            />
                        </label>
                        <p className="text-[0.68rem] leading-snug text-zinc-400 dark:text-zinc-500">
                            {DD_DOCUMENT_ALLOWED_HINT}
                        </p>
                    </div>

                    <div className="mt-3 rounded-xl border border-zinc-200 bg-zinc-50 p-3 dark:border-zinc-800 dark:bg-zinc-900/50">
                        {situacaoKey === 'suspenso' && (
                            <div className="flex flex-wrap justify-between items-center gap-2 text-[0.7rem] text-amber-600 dark:text-amber-400">
                                <div className="flex items-center gap-1.5">
                                    Processo suspenso em {dateFormater(form.watch('data_suspensao')) ?? ''} por <b>{responsavelName ?? ''}</b>
                                </div>
                                <Button
                                    size="flattened"
                                    type="button"
                                    disabled={
                                        isProcessoConcluido ||
                                        loadingStates.has('restoring')
                                    }
                                    onClick={() =>
                                        vm.handleUpdateProcesso(
                                            { situacao: DueDiligenceProcessosSituacao.ATIVO },
                                            PROCESSO_FORM_LOADING.restoring,
                                        )
                                    }
                                    className="rounded-lg border bg-transparent hover:bg-muted border-zinc-300 px-2 py-1 text-[0.68rem] font-semibold text-zinc-600 hover:border-zinc-400 dark:border-zinc-700 dark:text-zinc-300"
                                >
                                    {loadingStates.has(PROCESSO_FORM_LOADING.restoring) ? (
                                        <Loader className="size-3.5 animate-spin" />
                                    ) : (
                                        'Reativar'
                                    )}
                                </Button>
                            </div>
                        )}
                        {situacaoKey === 'arquivado' && (
                            <div className="w-full flex flex-wrap items-center justify-between gap-2 text-[0.7rem] text-zinc-600 dark:text-zinc-300">
                                <span className="inline-flex items-center gap-1.5">
                                    <Archive size={13} /> Processo Arquivado
                                </span>
                                <Button
                                    size="flattened"
                                    type="button"
                                    disabled={loadingStates.size > 0}
                                    onClick={() =>
                                        vm.handleUpdateProcesso(
                                            { situacao: DueDiligenceProcessosSituacao.ATIVO },
                                            PROCESSO_FORM_LOADING.restoring,
                                        )
                                    }
                                    className="rounded-lg border bg-transparent hover:bg-muted border-zinc-300 px-2 py-1 text-[0.68rem] font-semibold text-zinc-600 hover:border-zinc-400 dark:border-zinc-700 dark:text-zinc-300"
                                >
                                    {loadingStates.has(PROCESSO_FORM_LOADING.restoring) ? (
                                        <Loader className="size-3.5 animate-spin" />
                                    ) : (
                                        'Desarquivar'
                                    )}
                                </Button>
                            </div>
                        )}
                        {situacaoKey === 'ativo' && (
                            <div className="w-full grid grid-cols-4 gap-2">
                                <Button
                                    type="button"
                                    size="flattened"
                                    disabled={cannotAttachFiles}
                                    onClick={() =>
                                        vm.handleSuspenderProcesso(PROCESSO_FORM_LOADING.suspending)
                                    }
                                    className="inline-flex items-center gap-1 rounded-lg border border-amber-500/30 bg-amber-500/10 text-[0.68rem] font-semibold text-amber-600 hover:bg-amber-500/20 dark:text-amber-400"
                                >
                                    {loadingStates.has(PROCESSO_FORM_LOADING.suspending) ? (
                                        <Loader className="size-3 animate-spin" />
                                    ) : (
                                        <CircleStop size={12} />
                                    )}{' '}
                                    Suspender Processo
                                </Button>
                                <Button
                                    type="button"
                                    size="flattened"
                                    disabled={cannotAttachFiles}
                                    onClick={() =>
                                        vm.handleUpdateProcesso(
                                            { situacao: DueDiligenceProcessosSituacao.ARQUIVADO },
                                            PROCESSO_FORM_LOADING.archiving,
                                        )
                                    }
                                    className="inline-flex items-center gap-1 rounded-lg border border-zinc-400/30 bg-zinc-500/10 text-[0.68rem] font-semibold text-zinc-600 hover:bg-zinc-500/20 dark:text-zinc-300"
                                >
                                    {loadingStates.has(PROCESSO_FORM_LOADING.archiving) ? (
                                        <Loader className="size-3 animate-spin" />
                                    ) : (
                                        <Archive size={12} />
                                    )}{' '}
                                    Arquivar Processo
                                </Button>
                                <Button
                                    type="submit"
                                    size="flattened"
                                    disabled={lockedMain}
                                    className="rounded-lg bg-celer-blue text-[0.68rem] font-semibold text-white hover:bg-celer-blue-deep"
                                >
                                    <span className="inline-flex items-center gap-1.5">
                                        {loadingStates.has(PROCESSO_FORM_LOADING.saving) ? (
                                            <Loader className="size-3.5 animate-spin" />
                                        ) : (
                                            <Plus className="size-3.5" />
                                        )}
                                        Salvar Alterações
                                    </span>
                                </Button>
                                {!selectedProc.concluido ? (
                                    <Button
                                        type="button"
                                        size="flattened"
                                        disabled={cannotAttachFiles}
                                        onClick={() =>
                                            vm.handleUpdateProcesso(
                                                { concluido: true },
                                                PROCESSO_FORM_LOADING.concluding,
                                            )
                                        }
                                        className="rounded-lg bg-emerald-600 text-[0.68rem] font-semibold text-white hover:bg-emerald-700"
                                    >
                                        <span className="inline-flex items-center gap-1.5">
                                            {loadingStates.has(PROCESSO_FORM_LOADING.concluding) ? (
                                                <Loader className="size-3.5 animate-spin" />
                                            ) : (
                                                <Check className="size-3.5" />
                                            )}
                                            Concluir Processo
                                        </span>
                                    </Button>
                                ) : (
                                    <Button
                                        type="button"
                                        size="flattened"
                                        disabled={
                                            loadingStates.size > 0 ||
                                            isSavingAutosProcessos ||
                                            isSavingDocsAvulsos
                                        }
                                        onClick={() =>
                                            vm.handleUpdateProcesso(
                                                { concluido: false },
                                                PROCESSO_FORM_LOADING.reverting_conclusion,
                                            )
                                        }
                                        className="inline-flex items-center gap-1.5 rounded-lg border border-emerald-600/30 bg-emerald-600/10 text-[0.68rem] font-semibold text-emerald-700 hover:bg-emerald-600/20 dark:text-emerald-400"
                                    >
                                        {loadingStates.has(
                                            PROCESSO_FORM_LOADING.reverting_conclusion,
                                        ) ? (
                                            <Loader className="size-3.5 animate-spin" />
                                        ) : (
                                            <RefreshCw className="size-3.5" />
                                        )}
                                        Reverter conclusão
                                    </Button>
                                )}
                            </div>
                        )}
                    </div>
                </form>

                <PDFViewerModal
                    open={pdfViewer.open}
                    onOpenChange={handlePdfOpenChange}
                    fileUrl={pdfViewer.url}
                />
                {imagemPreview.open ? (
                    <ImgDocVisualizer onClose={handleCloseImagePreview} url={imagemPreview.url} />
                ) : null}
                {isGerenciarEspeciesOpen ? (
                    <GerenciarEspeciesProcessoModal
                        open={isGerenciarEspeciesOpen}
                        onOpenChange={setIsGerenciarEspeciesOpen}
                        especies={vm.especiesProcesso}
                        especiesQueryKey={vm.especiesProcessoQueryKey}
                        processosFormService={vm.processosFormService}
                    />
                ) : null}
            </>
        </TooltipProvider>
    );
}

