import { beforeAll, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { Form } from '@/components/ui/form';
import queryClient from '@/utils/queryClient';
import { QueryClientProvider } from '@tanstack/react-query';
import { fireEvent, render, screen } from '@testing-library/react';
import type { ComponentProps, ReactNode } from 'react';
import { useForm } from 'react-hook-form';
import { DueDiligenceProcessosSituacao } from '../../../../enums';
import type {
    IProcessosFormValues,
    IProcessosFormService,
    TProcessosFormLoadingStates,
} from '../../../../interfaces/processos';
import type { TProcessoJudicial } from '../../../../types/dueItem';
import { ProcessoFormView, type ProcessoFormViewModel } from '../ProcessoFormView';

jest.mock('@/components/Modals/BrokersDocs/ImgDocVizualizer', () => ({
    __esModule: true,
    default: () => null,
}));

jest.mock('@/components/Modals/Juridico/JuridicoCommonDialog', () => ({
    JuridicoCommonDialog: ({ trigger }: { trigger: ReactNode }) => <>{trigger}</>,
}));

jest.mock('@/components/Modals/PDFViewerModal', () => ({
    PDFViewerModal: () => null,
}));

jest.mock('@/components/Tooltips/GlobalTooltip', () => ({
    __esModule: true,
    default: ({ children }: { children: ReactNode }) => <>{children}</>,
}));

jest.mock('@/components/ui/checkbox', () => ({
    Checkbox: ({
        checked,
        disabled,
        id,
        onCheckedChange,
    }: {
        checked?: boolean;
        disabled?: boolean;
        id?: string;
        onCheckedChange?: (checked: boolean) => void;
    }) => (
        <input
            id={id}
            type="checkbox"
            checked={checked}
            disabled={disabled}
            onChange={(event) => onCheckedChange?.(event.target.checked)}
            readOnly={!onCheckedChange}
        />
    ),
}));

jest.mock('cleave.js/react', () => ({
    __esModule: true,
    default: (props: ComponentProps<'input'> & { options?: unknown; htmlRef?: unknown }) => {
        const inputProps = { ...props };
        delete inputProps.options;
        delete inputProps.htmlRef;

        return <input {...inputProps} />;
    },
}));

jest.mock('@/components/ui/select', () => ({
    Select: ({ children }: { children: ReactNode }) => <div>{children}</div>,
    SelectContent: ({ children }: { children: ReactNode }) => <div>{children}</div>,
    SelectItem: ({ children }: { children: ReactNode; value: string; className?: string }) => (
        <div>{children}</div>
    ),
    SelectTrigger: ({ children, className }: { children: ReactNode; className?: string }) => (
        <button type="button" className={className}>
            {children}
        </button>
    ),
    SelectValue: ({ placeholder }: { placeholder?: string }) => <span>{placeholder}</span>,
}));

jest.mock('@/components/ui/tooltip', () => ({
    TooltipProvider: ({ children }: { children: ReactNode }) => <>{children}</>,
}));

const baseProcesso: TProcessoJudicial = {
    polo: 'passivo',
    tipo: 'com_repercussao',
    natureza: 'conhecimento',
    situacao: DueDiligenceProcessosSituacao.ATIVO,
    especie: 'Ação de Cobrança',
    tribunal: 'TJSP',
    instancia: '1º Grau',
    juizo: '1ª Vara',
    fase: 'Conhecimento',
    concluido: false,
    npu: '0000000-00.0000.0.00.0000',
    pessoa_vinculada_id: 'pessoa-1',
    vinculado_a: 'pessoa',
    cedente_id: null,
    valor_causa: 1000,
    data_atualizacao: '2026-07-01',
    litispendencia: false,
    detalhes_litispendencia: '',
    resumo: 'Resumo',
    documento: null,
    docs_avulsos: [],
};

const processosFormService: IProcessosFormService = {
    getEspecies: async () => [{ id: 1, value: 'Ação de Cobrança' }],
    createEspecie: async ({ value }) => ({ id: 2, value }),
    updateEspecie: async (id, { value }) => ({ id, value }),
    deleteEspecie: async () => undefined,
    createProcesso: async () => baseProcesso,
    updateProcesso: async () => undefined,
    uploadAutosProcessos: async () => ({
        id: 1,
        nome_original: 'autos.pdf',
        arquivo_url: 'https://example.com/autos.pdf',
    }),
    uploadDocAvulso: async () => ({
        id: 1,
        nome_original: 'doc.pdf',
        descricao: 'doc',
        arquivo_url: 'https://example.com/doc.pdf',
    }),
    deleteDocAvulso: async () => undefined,
    deleteAutosProcessos: async () => undefined,
    contabilizarDivida: async () => undefined,
};

interface IProcessoFormViewHarnessProps {
    vmOverrides?: Partial<ProcessoFormViewModel>;
    selectedProcOverrides?: Partial<TProcessoJudicial>;
}

function ProcessoFormViewHarness({
    vmOverrides,
    selectedProcOverrides,
}: IProcessoFormViewHarnessProps) {
    const selectedProc: TProcessoJudicial = {
        ...baseProcesso,
        ...selectedProcOverrides,
    };
    const form = useForm<IProcessosFormValues>({
        defaultValues: {
            pessoa_vinculada_id: selectedProc.pessoa_vinculada_id ?? 'pessoa-1',
            polo: selectedProc.polo,
            tipo: selectedProc.tipo,
            natureza: selectedProc.natureza,
            situacao: selectedProc.situacao,
            especie: selectedProc.especie,
            tribunal: selectedProc.tribunal,
            instancia: selectedProc.instancia,
            juizo: selectedProc.juizo,
            fase: selectedProc.fase,
            npu: selectedProc.npu,
            valor_causa: selectedProc.valor_causa,
            data_atualizacao: selectedProc.data_atualizacao,
            litispendencia: selectedProc.litispendencia,
            detalhes_litispendencia: selectedProc.detalhes_litispendencia,
            resumo: selectedProc.resumo,
        },
    });
    const vm = {
        form,
        isFormLocked: false,
        situacaoKey: DueDiligenceProcessosSituacao.ATIVO,
        loadingStates: new Set(),
        isSavingAutosProcessos: false,
        isSavingDocsAvulsos: false,
        isContabilizandoDivida: false,
        deleteAutoProcessosMutation: { isPending: false },
        especiesProcesso: [
            { id: 1, value: 'Ação de Cobrança' },
            { id: 2, value: 'Ação Rescisória' },
        ],
        isEspeciesProcessoLoading: false,
        especiesProcessoQueryKey: ['due-diligence-processo-especies'],
        processosFormService,
        handleSubmitForm: jest.fn((event?: { preventDefault: () => void }) => {
            event?.preventDefault();
        }),
        pdfViewer: { open: false, url: '' },
        imagemPreview: { open: false, url: '' },
        handlePdfOpenChange: jest.fn(),
        handleCloseImagePreview: jest.fn(),
        handlePreviewDocumento: jest.fn(),
        handleUpdateProcesso: jest.fn(),
        handleDocumentoClear: jest.fn(),
        handleUploadAutosProcessos: jest.fn(),
        handleUploadOtherDocs: jest.fn(),
        handleDocsAvulsoRemove: jest.fn(),
        handleSuspenderProcesso: jest.fn(),
        handleContabilizarDivida: jest.fn(),
        ...vmOverrides,
    } as unknown as ProcessoFormViewModel;

    return (
        <QueryClientProvider client={queryClient}>
            <Form {...form}>
                <ProcessoFormView
                    vm={vm}
                    mode="create"
                    displayIndex={1}
                    tipoLabels={{
                        com_repercussao: 'Com repercussão',
                        sem_repercussao: 'Sem repercussão',
                    }}
                    isTerceiro={false}
                    processosContabilizados={[]}
                    pessoaId="pessoa-1"
                    onConfirmPrecatorioExclusao={jest.fn()}
                    selectedProc={selectedProc}
                />
            </Form>
        </QueryClientProvider>
    );
}

function getFileInputs(container: HTMLElement) {
    return Array.from(container.querySelectorAll('input[type="file"]')) as HTMLInputElement[];
}

describe('ProcessoFormView', () => {
    beforeAll(() => {
        global.ResizeObserver = jest.fn().mockImplementation(() => ({
            observe: jest.fn(),
            unobserve: jest.fn(),
            disconnect: jest.fn(),
        })) as unknown as typeof ResizeObserver;
        Element.prototype.scrollIntoView = jest.fn();
    });

    beforeEach(() => {
        queryClient.clear();
    });

    it('libera uploads e ações do footer para draft ativo sem id', () => {
        const { container } = render(<ProcessoFormViewHarness selectedProcOverrides={{ id: undefined }} />);

        expect(screen.queryByText(/salve o processo/i)).not.toBeInTheDocument();
        expect(getFileInputs(container)).toHaveLength(2);
        getFileInputs(container).forEach((input) => {
            expect(input).not.toBeDisabled();
        });
        expect(screen.getByRole('button', { name: /Suspender Processo/i })).not.toBeDisabled();
        expect(screen.getByRole('button', { name: /Arquivar Processo/i })).not.toBeDisabled();
        expect(screen.getByRole('button', { name: /Salvar Alterações/i })).not.toBeDisabled();
        expect(screen.getByRole('button', { name: /Concluir Processo/i })).not.toBeDisabled();
    });

    it('mantém uploads e ações do footer bloqueados durante lock operacional', () => {
        const { container } = render(
            <ProcessoFormViewHarness
                selectedProcOverrides={{ id: undefined }}
                vmOverrides={{
                    isFormLocked: true,
                }}
            />,
        );

        getFileInputs(container).forEach((input) => {
            expect(input).toBeDisabled();
        });
        expect(screen.getByRole('button', { name: /Suspender Processo/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Arquivar Processo/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Salvar Alterações/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Concluir Processo/i })).toBeDisabled();
    });

    it('mantém uploads e ações do footer bloqueados durante loading de ação', () => {
        const { container } = render(
            <ProcessoFormViewHarness
                selectedProcOverrides={{ id: undefined }}
                vmOverrides={{
                    loadingStates: new Set<TProcessosFormLoadingStates>(['archiving']),
                }}
            />,
        );

        getFileInputs(container).forEach((input) => {
            expect(input).toBeDisabled();
        });
        expect(screen.getByRole('button', { name: /Suspender Processo/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Arquivar Processo/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Salvar Alterações/i })).toBeDisabled();
        expect(screen.getByRole('button', { name: /Concluir Processo/i })).toBeDisabled();
    });

    it('renderiza espécie de processo como combobox com o valor preenchido', () => {
        render(<ProcessoFormViewHarness />);

        const especieCombobox = screen.getByRole('combobox', { name: 'Espécie de Processo' });
        expect(especieCombobox).toBeInTheDocument();
        expect(especieCombobox).toHaveTextContent('Ação de Cobrança');
        expect(especieCombobox).not.toBeDisabled();
    });

    it('preserva espécie customizada recebida da api no combobox', () => {
        render(
            <ProcessoFormViewHarness
                selectedProcOverrides={{
                    especie: 'Espécie Customizada da API',
                }}
            />,
        );

        expect(screen.getByRole('combobox', { name: 'Espécie de Processo' })).toHaveTextContent(
            'Espécie Customizada da API',
        );
    });

    it('bloqueia o combobox de espécie quando o formulário está locked', () => {
        render(
            <ProcessoFormViewHarness
                vmOverrides={{
                    isFormLocked: true,
                }}
            />,
        );

        expect(screen.getByRole('combobox', { name: 'Espécie de Processo' })).toBeDisabled();
    });

    it('atualiza a espécie selecionada como string no formulário', async () => {
        render(<ProcessoFormViewHarness />);

        fireEvent.click(screen.getByRole('combobox', { name: 'Espécie de Processo' }));
        fireEvent.click(await screen.findByText('Ação Rescisória'));

        expect(screen.getByRole('combobox', { name: 'Espécie de Processo' })).toHaveTextContent(
            'Ação Rescisória',
        );
    });

    it('abre o modal de gerenciamento a partir do campo de espécie', async () => {
        render(<ProcessoFormViewHarness />);

        fireEvent.click(screen.getByRole('combobox', { name: 'Espécie de Processo' }));
        fireEvent.click(await screen.findByText('Gerenciar espécies'));

        expect(
            await screen.findByRole('dialog', { name: 'Gerenciar espécies de processo' }),
        ).toBeInTheDocument();
    });

    it('renderiza litispendência como Sim/Não e mantém detalhamento sempre visível', () => {
        render(<ProcessoFormViewHarness />);

        expect(screen.getByRole('radio', { name: 'Não' })).toHaveAttribute('aria-checked', 'true');
        expect(screen.getByRole('radio', { name: 'Sim' })).toHaveAttribute('aria-checked', 'false');

        fireEvent.click(screen.getByRole('radio', { name: 'Sim' }));
        fireEvent.change(screen.getByLabelText('Detalhamento litispendência'), {
            target: { value: 'Processo duplicado.' },
        });

        expect(screen.getByRole('radio', { name: 'Sim' })).toHaveAttribute('aria-checked', 'true');
        expect(screen.getByLabelText('Detalhamento litispendência')).toHaveValue('Processo duplicado.');
    });
});

