'use client';

import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { m, useReducedMotion } from 'framer-motion';
import { Link, Plus, X } from 'lucide-react';

import {
    ADD_CEDENTE_SECTION_LABEL_CLASS,
    CEDENTE_SWITCHER_ITEM_ACTIVE_CLASS,
    CEDENTE_SWITCHER_ITEM_CLASS,
    CEDENTE_SWITCHER_SHELL_CLASS,
    SITUACAO_ADD_CEDENTE_BTN_CLASS,
} from '@/constants/due-diligence';
import { COLORS, ELEVATION } from '@/design-system';
import type { IAddCedenteSectionProps, ICedenteSwitcherProps } from '../../../interfaces/situacaoJuridicaViews';
import { isCessaoTotalmentePreenchida } from '../../../utils/situacaoJuridicaCedente';
import { getCedenteTipoLabel } from '../../../utils/situacaoJuridicaDisplay';
import {
    getSituacaoEnterMotion,
    getTitleThenCardsDelays,
    SITUACAO_STAGGER_STEP,
} from '../../../utils/situacaoJuridicaMotion';
import { CessaoPercentualSection } from '../Alerts/CessaoPercentualSection';
import { StatusPingDot } from '../StatusPingDot';

function AddCedentePills({
    onAddCedente,
    onLinkExistingCedente,
    canAddCedente = true,
    baseDelay = 0,
    reduceMotion = false,
}: IAddCedenteSectionProps & { baseDelay?: number; reduceMotion?: boolean | null }) {
    if (!canAddCedente) {
        return null;
    }

    const cedenteTipos = ['PF', 'PJ', 'ES'] as const;
    const { titleDelay, firstCardDelay } = getTitleThenCardsDelays(cedenteTipos.length, baseDelay);

    return (
        <div
            className="min-w-0"
            role="group"
            aria-labelledby="add-cedente-section-label"
        >
            <m.span
                id="add-cedente-section-label"
                {...getSituacaoEnterMotion(reduceMotion, titleDelay)}
                className={ADD_CEDENTE_SECTION_LABEL_CLASS}
            >
                Adicionar novo cedente
            </m.span>
            <div className="flex flex-wrap items-center gap-2">
                {cedenteTipos.map((tipo, index) => (
                    <m.div
                        key={tipo}
                        {...getSituacaoEnterMotion(reduceMotion, firstCardDelay + index * SITUACAO_STAGGER_STEP)}
                    >
                        <Button
                            type="button"
                            variant="outline"
                            size="flattened"
                            onClick={() => onAddCedente(tipo)}
                            style={{
                                backgroundColor: COLORS.card,
                                borderColor: COLORS.line,
                                boxShadow: ELEVATION.surfaceRest,
                            }}
                            className={SITUACAO_ADD_CEDENTE_BTN_CLASS}
                        >
                            <Plus size={14} aria-hidden />
                            {getCedenteTipoLabel(tipo)}
                        </Button>
                    </m.div>
                ))}
                {onLinkExistingCedente ? (
                    <m.div
                        {...getSituacaoEnterMotion(
                            reduceMotion,
                            firstCardDelay + cedenteTipos.length * SITUACAO_STAGGER_STEP,
                        )}
                    >
                        <Button
                            type="button"
                            variant="outline"
                            size="flattened"
                            onClick={onLinkExistingCedente}
                            aria-label="Vincular cedente existente"
                            style={{
                                backgroundColor: COLORS.card,
                                borderColor: COLORS.line,
                                boxShadow: ELEVATION.surfaceRest,
                            }}
                            className={SITUACAO_ADD_CEDENTE_BTN_CLASS}
                        >
                            <Link size={14} aria-hidden />
                            vincular cedente existente
                        </Button>
                    </m.div>
                ) : null}
            </div>
        </div>
    );
}

export function CedenteSwitcher({
    cedentesState,
    activeCedente,
    cessaoPercentualResumo,
    onSetActiveCedente,
    onAddCedente,
    onLinkExistingCedente,
    onRemoveCedente,
    isDesvinculandoCedente = false,
}: ICedenteSwitcherProps) {
    const reduceMotion = useReducedMotion();

    if (cedentesState.length === 0) {
        return null;
    }

    const showTabs = cedentesState.length > 1;
    const tabsCompleteDelay = showTabs
        ? getTitleThenCardsDelays(cedentesState.length, 0).cardsCompleteDelay
        : 0;
    const addSectionBaseDelay = showTabs ? tabsCompleteDelay + SITUACAO_STAGGER_STEP : 0;
    const cessaoSectionDelay = Math.max(0, addSectionBaseDelay - SITUACAO_STAGGER_STEP * 0.5);
    const canAddCedente = !isCessaoTotalmentePreenchida(cessaoPercentualResumo);

    return (
        <div className="mb-4 flex w-full min-w-0 flex-col gap-3">
            {cessaoPercentualResumo ? (
                <CessaoPercentualSection
                    resumo={cessaoPercentualResumo}
                    baseDelay={cessaoSectionDelay}
                    reduceMotion={reduceMotion}
                    className="w-full"
                />
            ) : null}
            <div className="flex w-full min-w-0 flex-wrap items-center gap-x-3 gap-y-2">
                {showTabs ? (
                    <div
                        className={cn(CEDENTE_SWITCHER_SHELL_CLASS, 'min-w-0 shrink-0')}
                        role="tablist"
                        aria-label="Selecionar cedente"
                    >
                        {cedentesState.map((cedenteItem, index) => {
                            const isActive = index === activeCedente;
                            const cedente = cedenteItem.cedente;
                            const hasPending =
                                !cedente.processos_concluidos || !cedente.certidoes_concluidas;

                            return (
                                <m.div
                                    key={cedenteItem.id || cedente.id || `cedente-tab-${index}`}
                                    {...getSituacaoEnterMotion(reduceMotion, index * SITUACAO_STAGGER_STEP)}
                                    className="relative"
                                >
                                    <button
                                        type="button"
                                        role="tab"
                                        aria-selected={isActive}
                                        onClick={() => onSetActiveCedente(index)}
                                        className={cn(
                                            CEDENTE_SWITCHER_ITEM_CLASS,
                                            'min-w-[120px] max-w-[200px] pr-7',
                                            isActive && CEDENTE_SWITCHER_ITEM_ACTIVE_CLASS,
                                        )}
                                    >
                                        <span className="flex items-center gap-1.5">
                                            <span className="truncate text-sm font-semibold text-foreground">
                                                {cedente.nome || `Cedente ${index + 1}`}
                                            </span>
                                            <StatusPingDot
                                                hasPending={hasPending}
                                                size="sm"
                                                aria-label={
                                                    hasPending
                                                        ? 'Análises pendentes'
                                                        : 'Análises concluídas'
                                                }
                                            />
                                        </span>
                                        <span className="mt-0.5 block font-mono text-[10px] text-muted-foreground">
                                            {getCedenteTipoLabel(cedente.tipo)}
                                        </span>
                                    </button>
                                    <JuridicoCommonDialog
                                        title="Desvincular cedente do ofício"
                                        description={`O vínculo de ${cedente.nome} com este ofício será removido. O cadastro do cedente permanece no sistema.`}
                                        confirmButtonText="Desvincular"
                                        confirmButtonFn={() => onRemoveCedente(index, cedenteItem.id)}
                                        trigger={
                                            <button
                                                type="button"
                                                disabled={isDesvinculandoCedente}
                                                className="absolute right-1 top-1 flex size-5 items-center justify-center rounded-md text-(--text-muted) transition-colors hover:bg-red-500/10 hover:text-red-600 disabled:pointer-events-none disabled:opacity-50"
                                                aria-label={`Desvincular cedente ${cedente.nome || index + 1} do ofício`}
                                            >
                                                <X size={11} aria-hidden />
                                            </button>
                                        }
                                    />
                                </m.div>
                            );
                        })}
                    </div>
                ) : null}
                {showTabs && canAddCedente ? (
                    <m.div
                        {...getSituacaoEnterMotion(
                            reduceMotion,
                            tabsCompleteDelay + SITUACAO_STAGGER_STEP * 0.5,
                        )}
                        className="hidden h-9 shrink-0 sm:block"
                    >
                        <Separator orientation="vertical" className="h-full" />
                    </m.div>
                ) : null}
                <AddCedentePills
                    onAddCedente={onAddCedente}
                    onLinkExistingCedente={onLinkExistingCedente}
                    canAddCedente={canAddCedente}
                    baseDelay={addSectionBaseDelay}
                    reduceMotion={reduceMotion}
                />
            </div>
        </div>
    );
}

