'use client';

import { CessionarioMetricsGrid } from '@/components/Juridico/Details/CessionarioMetricsGrid';
import { PadraoDuePill } from '@/components/Juridico/Details/PadraoDuePill';
import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
import { Button } from '@/components/ui/button';
import { productDialogOutlineButtonClass } from '@/design-system';
import { maskCpfCnpj } from '@/functions/formaters/maskPii';
import { useCessionarioVinculadoUnlinkMutation } from '@/hooks/mutations/useCessionarioVinculadoMutations';
import { cn } from '@/lib/utils';
import {
    resolveEffectiveDelimitador,
    resolvePctAquisicaoInvestidorDisplay,
    resolveVinculoDisplayName,
    resolveVinculoDocumento,
} from '@/services/cessionario-vinculado';
import type { DueCessionarioVinculado } from '@/types/due-diligence';
import { LoaderCircle, PencilLine, Sparkles, Trash2 } from 'lucide-react';
import { VinculadoCessionarioEditModal } from './VinculadoCessionarioEditModal';

interface VinculadoCessionarioManageCardProps {
    vinculo: DueCessionarioVinculado;
    dueId: string;
    extratoId?: string;
    isLocked?: boolean;
}

function formatPercentual(value: string | number | null | undefined): string {
    if (value === null || value === undefined || value === '') return '—';
    const numeric = Number(value);
    if (Number.isNaN(numeric)) return String(value);
    return `${numeric.toLocaleString('pt-BR', { maximumFractionDigits: 2 })}%`;
}

function formatDelimitador(vinculo: DueCessionarioVinculado): string {
    const { ativo, percentual } = resolveEffectiveDelimitador(vinculo);
    if (!ativo) return 'Não aplica';
    if (percentual == null) return 'Sem teto';
    return formatPercentual(percentual);
}

function TipoChip({ tipo }: { tipo: string }) {
    const isPf = tipo?.toUpperCase() === 'PF';
    return (
        <span
            className={cn(
                'inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide',
                isPf
                    ? 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300'
                    : 'bg-sky-500/10 text-sky-700 dark:text-sky-300',
            )}
        >
            {isPf ? 'PF' : 'PJ'}
        </span>
    );
}

export function VinculadoCessionarioManageCard({
    vinculo,
    dueId,
    extratoId,
    isLocked = false,
}: VinculadoCessionarioManageCardProps) {
    const unlinkMutation = useCessionarioVinculadoUnlinkMutation(dueId, extratoId);
    const nome = resolveVinculoDisplayName(vinculo);
    const documento = resolveVinculoDocumento(vinculo);
    const documentLabel = documento ? maskCpfCnpj(documento) || documento : '—';
    const aquisicaoDisplay = resolvePctAquisicaoInvestidorDisplay(
        vinculo.percentual_aquisicao_investidor,
        vinculo.percentual_aquisicao_investidor_efetivo,
    );
    const isSmartblockAuto = vinculo.origem === 'smartblock_auto';
    const tipo = vinculo.cessionario?.tipo ?? 'pf';
    const padraoDue = vinculo.cessionario?.padrao_due ?? null;

    const actionButtons = !isLocked ? (
        <div className="flex shrink-0 items-center gap-1">
            <VinculadoCessionarioEditModal
                vinculo={vinculo}
                dueId={dueId}
                extratoId={extratoId}
                triggerButton={
                    <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className={cn(productDialogOutlineButtonClass, 'h-8 gap-1.5 px-2.5 text-xs')}
                        aria-label={`Editar ${nome}`}
                    >
                        <PencilLine className="size-3.5" aria-hidden />
                        Editar
                    </Button>
                }
            />
            <JuridicoCommonDialog
                title="Remover investidor desta operação?"
                description={`${nome} deixará de constar nesta due. O cadastro do investidor no sistema permanece.`}
                confirmButtonText="Remover investidor"
                confirmButtonFn={() => unlinkMutation.mutate(vinculo.id)}
                cancelButtonText="Cancelar"
                trigger={
                    <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="h-8 gap-1.5 px-2.5 text-xs text-destructive hover:bg-destructive/10 hover:text-destructive"
                        disabled={unlinkMutation.isPending}
                        aria-label={`Remover ${nome}`}
                    >
                        {unlinkMutation.isPending ? (
                            <LoaderCircle className="size-3.5 animate-spin" aria-hidden />
                        ) : (
                            <Trash2 className="size-3.5" aria-hidden />
                        )}
                        Remover
                    </Button>
                }
            />
        </div>
    ) : null;

    return (
        <article className="rounded-2xl border border-border/80 bg-(--paper-surface) p-4 shadow-[0_1px_2px_rgba(15,23,42,0.06)] dark:border-white/10 dark:bg-(--graphite-panel)">
            <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0 space-y-1.5">
                    <div className="flex min-w-0 flex-wrap items-center gap-2">
                        <h3
                            className="truncate font-satoshi text-sm font-bold tracking-tight text-foreground"
                            title={nome}
                        >
                            {nome}
                        </h3>
                        <TipoChip tipo={tipo} />
                        <PadraoDuePill value={padraoDue} />
                        {isSmartblockAuto ? (
                            <span
                                className="inline-flex items-center gap-1 rounded-md bg-celer-blue/8 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-celer-blue"
                                title="Vinculado pela regra do bloco comercial"
                            >
                                <Sparkles className="size-2.5" aria-hidden />
                                Automático
                            </span>
                        ) : null}
                    </div>
                    {vinculo.cessionario?.gestora_nome ? (
                        <p
                            className="truncate text-xs text-muted-foreground"
                            title={vinculo.cessionario.gestora_nome}
                        >
                            Gestora: {vinculo.cessionario.gestora_nome}
                        </p>
                    ) : null}
                    <p className="truncate font-mono text-[13px] font-semibold tabular-nums text-muted-foreground">
                        {documentLabel}
                    </p>
                </div>
                {actionButtons}
            </div>

            <div className="mt-4">
                <CessionarioMetricsGrid
                    percentualCessao={formatPercentual(vinculo.percentual)}
                    aquisicaoInvestidor={aquisicaoDisplay}
                    delimitador={formatDelimitador(vinculo)}
                />
            </div>
        </article>
    );
}

