    JuridicoDueDiligenceStatus,
    JuridicoDueDiligenceStatusFinalization,
    JuridicoDueDiligenceStatusFinalizationLabels,
    JuridicoDueDiligenceStatusLabels,
} from '@/enums/dueDiligence';
import { backendDataFormat } from '@/functions/formaters/backendDataFormat';
import {
    captureDuePhaseTransitionFailed,
    captureDuePhaseTransitionSucceeded,
    captureDueV1OficioRefetchFailed,
    captureDueV1PosFlowFailed,
    captureDueV1PosFlowStarted,
    captureDueV1PosFlowSuccess,
} from '@/functions/analytics/dueDiligencePhaseAnalytics';
import { getUserFacingApiMessage } from '@/functions/analytics/axiosErrorProps';
import {
    applyDuePendingRequirementsFailure,
    buildPendingRequirementsToastMessage,
    scrollToDuePendingRequirements,
    toDueInputErrorTypes,
} from '@/functions/juridico/due-pending-requirements-flow';
import {
    computeCurrentPhasePendingRequirements,
    computePendingRequirementsForTransition,
} from '@/functions/juridico/due-status-transition';
import { resolveRepactuacaoErrorFeedback } from '@/functions/juridico/resolveRepactuacaoErrorFeedback';
import { DuePendingRequirementsPreview } from '@/components/Juridico/Details/DuePendingRequirementsPreview';
import { mapDueStatusDisplayForV1Ui } from '@/functions/juridico/mapDueStatusDisplayForV1Ui';
import { TOAST_LOADING_ID, sendToastMessage } from '@/functions/messages/toastMessage';
import { sleep } from '@/functions/timer/sleep';
import { useOficioLinkedCedentesQuery } from '@/hooks/queries/cedentes';
import { createNewComment } from '@/services/BrokerServices';
import { sendProposalToRepactuacao } from '@/services/DetailsJuridicoServices';
import {
    fetchDueDiligenceData,
    removeDuePendecia,
    sendDueToPendencies,
    updateDueField,
} from '@/services/due-diligence';
import { createProcessualMove } from '@/services/processual-moves';
import { ItensChecklist, type DueDiligenceDetailed } from '@/types/due-diligence';
import { DetailedOficioProps, OficioDueDiligence } from '@/types/oficio';
import { useJuridicoDetailsStore } from '@/store/useJuridicoDetailsStore';
import queryClient from '@/utils/queryClient';
import { AxiosError } from 'axios';
import 'driver.js/dist/driver.css';
import { AnimatePresence, m, useReducedMotion } from 'framer-motion';
import {
    Archive,
    ArrowLeft,
    ArrowRight,
    ArrowRightLeft,
    Calendar,
    Check,
    ChevronDown,
    LoaderCircle,
    Menu,
    TextSearch,
    X,
} from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { useMemo, useState } from 'react';
import ReactDOM from 'react-dom';
import { cn } from '@/lib/utils';
import { JuridicoActionDock } from './JuridicoActionDock';
import { JuridicoActionDockListRow } from './JuridicoActionDockListRow';
import {
    productDialogDescriptionClass,
    productDialogTitleClass,
} from '@/design-system';
import {
    juridicoActionDockClosedShellMotion,
    juridicoActionDockItemReducedVariants,
    juridicoActionDockItemVariants,
    juridicoActionDockListReducedVariants,
    juridicoActionDockListVariants,
    juridicoActionDockOpenShellMotion,
    juridicoActionDockPanelSwapVariants,
    juridicoActionDockShellTransition,
    juridicoActionDockSwapReducedVariants,
    juridicoActionDockTriggerSwapVariants,
} from '@/design-system/motion/juridico-action-dock-motion';
import {
    juridicoActionDockActionButtonClass,
    juridicoActionDockBodyClass,
    juridicoActionDockChevronClass,
    juridicoActionDockHeaderClass,
    juridicoActionDockListClass,
    juridicoActionDockShellClass,
    juridicoActionDockStatusLabelClass,
    juridicoActionDockStatusRowClass,
    juridicoActionDockTriggerClass,
    juridicoActionDockTriggerIconClass,
    juridicoActionDockTriggerSubtitleClass,
    juridicoActionDockTriggerTitleClass,
} from './juridico-action-dock-styles';

const JuridicoDetailsFloatActionMenu = ({
    data,
    activeDue,
    dueId,
    dueStatusCode,
    requirementsData,
    statusDisplayForUi,
    statusLiquidacao,
}: {
    data: DetailedOficioProps;
    activeDue: OficioDueDiligence | undefined;
    /** ID da due da página (invalidação de requisitos e status_display). */
    dueId: string;
    /** Código cru do status da due da página (pode divergir de `activeDue` no ofício). */
    dueStatusCode?: string;
    requirementsData: ItensChecklist[];
    /** Rótulo já normalizado V2→V1 (opcional; senão mapeia a partir de activeDue). */
    statusDisplayForUi?: string;
    statusLiquidacao?: string | null;
}) => {
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    /** Mantém `max-h` do shell até o painel terminar o exit (evita “pulo” de altura ao fechar). */
    const [isDockLayoutExpanded, setIsDockLayoutExpanded] = useState(false);
    const prefersReducedMotion = useReducedMotion() === true;

    function openDockMenu() {
        setIsDockLayoutExpanded(true);
        setIsMenuOpen(true);
    }

    function closeDockMenu() {
        setIsMenuOpen(false);
    }

    function handleDockExitComplete() {
        if (!isMenuOpen) {
            setIsDockLayoutExpanded(false);
        }
    }
    const isShellExpanded = isMenuOpen || isDockLayoutExpanded;
    const dockShellTransition = useMemo(
        () => juridicoActionDockShellTransition(prefersReducedMotion),
        [prefersReducedMotion],
    );
    const dockTriggerSwapVariants = prefersReducedMotion
        ? juridicoActionDockSwapReducedVariants
        : juridicoActionDockTriggerSwapVariants;
    const dockPanelSwapVariants = prefersReducedMotion
        ? juridicoActionDockSwapReducedVariants
        : juridicoActionDockPanelSwapVariants;
    const dockListVariants = prefersReducedMotion
        ? juridicoActionDockListReducedVariants
        : juridicoActionDockListVariants;
    const dockItemVariants = prefersReducedMotion
        ? juridicoActionDockItemReducedVariants
        : juridicoActionDockItemVariants;

    const [loadingState, setLoadingState] = useState<string | null>(null);
    const statusDiligence: string =
        statusDisplayForUi ||
        mapDueStatusDisplayForV1Ui({
            statusCode: activeDue?.status,
            statusDisplay: activeDue?.status_display,
            statusLiquidacao,
        });
    const currentVigenteProposal = data.propostas?.find((proposal) => proposal.vigente);

    // ================
    // # React Query
    // ================
    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(data.id);

    const cessionariosList = useMemo(() => {
        return (
            linkedCedentesList?.filter(
                (cedente) => cedente.cedente?.tipo_do_cedente === 'CESSIONARIO',
            ) || []
        );
    }, [linkedCedentesList]);

    const currentDueStatus = activeDue?.status ?? '';
    const dueDetailsId = dueId || activeDue?.id;
    const { data: dueDetailsForSmartblock } = useQuery<DueDiligenceDetailed>({
        queryKey: [QueryKeys.dueDiligence.details, dueDetailsId],
        queryFn: () => {
            if (!dueDetailsId) {
                throw new Error('Missing due details id');
            }
            return fetchDueDiligenceData(dueDetailsId);
        },
        enabled: Boolean(dueDetailsId),
        retry: false,
    });
    const smartblockCessionario = dueDetailsForSmartblock?.smartblock_cessionario ?? null;

    function buildPhaseAdvance(targetStatus: string) {
        if (!currentDueStatus) {
            return undefined;
        }

        return {
            currentStatus: currentDueStatus,
            targetStatus,
            requirementsData,
            esfera: data.esfera,
        };
    }

    const dueRequisitosOptions = useMemo(
        () => ({ esfera: data.esfera }),
        [data.esfera],
    );

    const dockPendingRequirements = useMemo(() => {
        if (!currentDueStatus || requirementsData.length === 0) {
            return [];
        }

        return computeCurrentPhasePendingRequirements(
            requirementsData,
            currentDueStatus,
            dueRequisitosOptions,
        );
    }, [currentDueStatus, requirementsData, dueRequisitosOptions]);

    // =========================
    // # Handlers
    // =========================
    const refetchExtratoData = async () => {
        const dueIdToRefresh = dueId || activeDue?.id;
        try {
            await sleep(TOAST_INTERVAL_AWAIT_PROMISE);
            sendToastMessage({
                type: 'loading',
                title: 'Atualizando dados do ofício.',
            });
            await Promise.all([
                queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item, data.id] }),
                queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item] }),
                queryClient.invalidateQueries({ queryKey: [QueryKeys.juridico.liquidation] }),
                queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.dashboardCounts] }),
                queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.liquidationCounts] }),
                queryClient.invalidateQueries({ queryKey: [QueryKeys.dueDiligence.listSummary] }),
                ...(dueIdToRefresh
                    ? [
                          queryClient.invalidateQueries({
                              queryKey: [QueryKeys.dueDiligence.details, dueIdToRefresh],
                          }),
                          queryClient.invalidateQueries({
                              queryKey: [
                                  QueryKeys.dueDiligence.dueRequirementsChecks,
                                  dueIdToRefresh,
                              ],
                          }),
                      ]
                    : []),
            ]);
            sendToastMessage({
                type: 'success',
                title: 'Dados do ofício atualizados com sucesso!',
                previousToastId: TOAST_LOADING_ID,
            });
        } catch (error) {
            captureDueV1OficioRefetchFailed(
                {
                    due_id: dueIdToRefresh ?? '',
                    extrato_id: data.id,
                    from_status: currentDueStatus,
                },
                error,
            );
            throw error;
        }
    };

    const handlePendencia = async (formData: JuridicoExigenciaFormData) => {
        setLoadingState(ComercialPendenciesStatus.PENDENCIA_A_SANAR);
        try {
            const exigenciasPayload = [
                {
                    motivo: formData.reason,
                    video_url: formData.videoUrl || undefined,
                    requer_documentos: formData.requerDocumentos,
                    comentarios: formData.comentarios?.map((c) => c.texto),
                },
                ...(formData.extras || []).map((extra) => ({
                    motivo: extra.motivo,
                    video_url: extra.videoUrl || undefined,
                    requer_documentos: extra.requerDocumentos,
                    comentarios: [],
                })),
            ].filter((item) => item.motivo || item.video_url);

            const payload = {
                motivo: formData.reason,
                video_url: formData.videoUrl || undefined,
                comentarios: formData.comentarios?.map((c) => c.texto),
                exigencias: exigenciasPayload,
            };
            const res = await sendDueToPendencies(activeDue?.id ?? '', payload);
            sendToastMessage({
                title: res.message,
                type: 'success',
            });

            // criando movimentação processual
            await handleCreateMovimentacao(formData.reason);

            // refazendo fetch dos dados do oficio
            await refetchExtratoData();
        } catch (error) {
            console.error(error);
            sendToastMessage({
                title: 'Houve um erro ao enviar ofício para pendência.',
                type: 'error',
            });
        } finally {
            setLoadingState(null);
            closeDockMenu();
        }
    };

    const handleRemovePendencia = async (check: boolean) => {
        setLoadingState('PENDENCIA_SANADA');
        try {
            const payload = {
                ajustar_prazo: check,
            };

            await removeDuePendecia(activeDue?.id ?? '', payload);
            sendToastMessage({
                title: 'Pendência removida com sucesso.',
                type: 'success',
            });

            // refazendo fetch dos dados do oficio
            await refetchExtratoData();
        } catch (error) {
            console.error(error);
            sendToastMessage({
                title: 'Houve um erro ao remover pendência.',
                type: 'error',
            });
        } finally {
            closeDockMenu();
            setLoadingState(null);
        }
    };

    const handleCreateMovimentacao = async (reason: string) => {
        try {
            const payload = {
                extratoId: data.id,
                descricao: reason,
                data: backendDataFormat(new Date()) ?? '',
            };
            await createProcessualMove(payload);
        } catch (error) {
            console.error(error);
            sendToastMessage({
                title: 'Houve um erro ao criar movimentação processual.',
                type: 'error',
            });
        }
    };

    async function handleDueArchived() {
        await refetchExtratoData();
        queryClient.invalidateQueries({
            queryKey: [QueryKeys.dueDiligence.list],
            refetchType: 'all',
        });
        closeDockMenu();
    }

    const handleRepactuacao = async (formData: JuridicoExigenciaFormData) => {
        setLoadingState('Repactuação');
        try {
            const exigenciasPayload = [
                {
                    motivo: formData.reason,
                    video_url: formData.videoUrl || undefined,
                    requer_documentos: formData.requerDocumentos,
                    comentarios: formData.comentarios?.map((c) => c.texto),
                },
                ...(formData.extras || []).map((extra) => ({
                    motivo: extra.motivo,
                    video_url: extra.videoUrl || undefined,
                    requer_documentos: extra.requerDocumentos,
                    comentarios: [],
                })),
            ].filter((item) => item.motivo || item.video_url);

            const payload = {
                video_url: formData.videoUrl || undefined,
                comentarios: formData.comentarios?.map((c) => c.texto),
                exigencias: exigenciasPayload,
            };
            await sendProposalToRepactuacao(
                currentVigenteProposal?.uuid as string,
                formData.reason,
                payload,
            );

            sendToastMessage({
                title: 'Ofício movido para área de Repactuação.',
                type: 'success',
            });
            await refetchExtratoData();
            closeDockMenu();
        } catch (error) {
            console.error(error);
            sendToastMessage(
                resolveRepactuacaoErrorFeedback(
                    error,
                    'Houve um erro ao enviar ofício para repactuação.',
                ),
            );
        } finally {
            setLoadingState(null);
        }
    };

    const handleAprovarComRessalva = async (status: string, reason: string) => {
        const resposeStatus = await handleUpdateDuePhase(status);

        if (resposeStatus === 200) {
            const messageToSend = `[RESSALVA]: ${reason}`;
            const responseStatus = await createNewComment(data.id, messageToSend);

            if (responseStatus === 201) {
                sendToastMessage({
                    title: 'Comentário com ressalva adicionado a seção.',
                    type: 'success',
                });
                return;
            }

            sendToastMessage({
                title: 'Houve um erro ao adicionar comentário com ressalva.',
                type: 'error',
            });
        }
    };

    const handleUpdateDuePhase = async (statusValue: string): Promise<number> => {
        setLoadingState(statusValue);

        const clientPending = computePendingRequirementsForTransition(
            requirementsData,
            currentDueStatus,
            statusValue,
            dueRequisitosOptions,
        );

        if (clientPending.length > 0) {
            useJuridicoDetailsStore
                .getState()
                .setRequiredInputsErrorType(toDueInputErrorTypes(clientPending));

            closeDockMenu();
            scrollToDuePendingRequirements(clientPending, 320);

            sendToastMessage({
                title: buildPendingRequirementsToastMessage(clientPending),
                type: 'error',
            });

            captureDuePhaseTransitionFailed(
                activeDue?.id ?? '',
                statusValue,
                new Error('Client-side pending requirements gate'),
                clientPending.length,
                {
                    extrato_id: data.id,
                    from_status: currentDueStatus,
                    ui_version: 'v1',
                },
            );

            setLoadingState(null);
            return 400;
        }

        const dueIdForAnalytics = activeDue?.id ?? '';
        const isConcluirPos = statusValue === 'CONCLUIDO';

        if (isConcluirPos) {
            captureDueV1PosFlowStarted({
                due_id: dueIdForAnalytics,
                extrato_id: data.id,
                from_status: currentDueStatus,
                target_status: statusValue,
                step: 'concluir',
            });
        }

        try {
            await updateDueField(dueIdForAnalytics, { status: statusValue });
            captureDuePhaseTransitionSucceeded({
                due_id: dueIdForAnalytics,
                extrato_id: data.id,
                from_status: currentDueStatus,
                target_status: statusValue,
                ui_version: 'v1',
            });
            sendToastMessage({
                title: 'Status da diligência alterado com sucesso.',
                type: 'success',
                previousToastId: TOAST_LOADING_ID
            });
            await refetchExtratoData();
            if (isConcluirPos) {
                captureDueV1PosFlowSuccess({
                    due_id: dueIdForAnalytics,
                    extrato_id: data.id,
                    from_status: currentDueStatus,
                    target_status: statusValue,
                    step: 'concluir',
                });
            }
            closeDockMenu();
            return 200;
        } catch (error) {
            console.error(error);

            if (isConcluirPos) {
                captureDueV1PosFlowFailed(
                    {
                        due_id: dueIdForAnalytics,
                        extrato_id: data.id,
                        from_status: currentDueStatus,
                        target_status: statusValue,
                        step: 'concluir',
                    },
                    error,
                );
            }

            if (
                applyDuePendingRequirementsFailure(error, {
                    dueId: dueIdForAnalytics,
                    targetStatus: statusValue,
                    onCloseOverlay: closeDockMenu,
                })
            ) {
                return 400;
            }

            if (error instanceof AxiosError) {
                sendToastMessage({
                    title: getUserFacingApiMessage(
                        error,
                        'Houve um erro ao alterar o status da diligência.',
                    ),
                    type: 'error',
                    previousToastId: TOAST_LOADING_ID,
                });

                captureDuePhaseTransitionFailed(
                    dueIdForAnalytics,
                    statusValue,
                    error,
                    0,
                    {
                        extrato_id: data.id,
                        from_status: currentDueStatus,
                        ui_version: 'v1',
                    },
                );
            }

            return 400;
        } finally {
            setLoadingState(null);
        }
    };

    // =========================
    // # Render
    // =========================
    return ReactDOM.createPortal(
        <JuridicoActionDock isExpanded={isMenuOpen}>
            <m.div
                layout={!prefersReducedMotion}
                initial={juridicoActionDockClosedShellMotion}
                animate={
                    isShellExpanded
                        ? juridicoActionDockOpenShellMotion
                        : juridicoActionDockClosedShellMotion
                }
                transition={dockShellTransition}
                className={cn(
                    'pointer-events-auto flex w-full flex-col overflow-hidden',
                    juridicoActionDockShellClass,
