                                            Ações da due diligence
                                        </h2>
                                        <p className={productDialogDescriptionClass}>
                                            Pendências, repactuação e avanço de fase deste ofício.
                                        </p>
                                    </div>
                                    <ChevronDown
                                        size={16}
                                        className={cn(
                                            juridicoActionDockChevronClass,
                                            'mt-1 rotate-180',
                                        )}
                                        aria-hidden
                                    />
                            </div>

                            <div className={juridicoActionDockBodyClass}>
                                    <div className={juridicoActionDockStatusRowClass}>
                                        <span className={juridicoActionDockStatusLabelClass}>
                                            Status
                                        </span>
                                        <CommonBadge
                                            options={{
                                                info: {
                                                    color: 'blue',
                                                    name: statusDiligence,
                                                },
                                                dot: true,
                                            }}
                                        />
                                    </div>
                                {dockPendingRequirements.length > 0 && (
                                    <DuePendingRequirementsPreview
                                        requisitos={dockPendingRequirements}
                                        title="Conclua estes itens antes de avançar para a próxima fase."
                                    />
                                )}
                                <m.div
                                    role="list"
                                    variants={dockListVariants}
                                    initial="hidden"
                                    animate="visible"
                                    className={juridicoActionDockListClass}
                                >
                            {statusDiligence !==
                                ComercialPendenciesStatusLabels.PENDENCIA_A_SANAR && (
                                    <JuridicoExigenciaModal
                                        title="Pendência a Sanar"
                                        description="Você está prestes a enviar o ofício para Pendências."
                                        label="Informe o motivo"
                                        submitFn={(data: JuridicoExigenciaFormData) =>
                                            handlePendencia(data)
                                        }
                                        confirmButtonText="Enviar"
                                        trigger={
                                            <JuridicoActionDockListRow variants={dockItemVariants}>
                                                <Button
                                                    disabled={loadingState !== null}
                                                    size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-red-100 text-red-600 dark:bg-red-950/60 dark:text-red-400">
                                                        {loadingState ===
                                                            ComercialPendenciesStatus.PENDENCIA_A_SANAR ? (
                                                            <LoaderCircle
                                                                size={16}
                                                                className="animate-spin"
                                                            />
                                                        ) : (
                                                            <X size={16} />
                                                        )}
                                                    </div>
                                                    <div className="text-left">
                                                        <p className="text-sm font-semibold leading-tight text-foreground">
                                                            Pendência a Sanar
                                                        </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Envia ofício para resolução de pendências
                                                        </p>
                                                    </div>
                                                </Button>
                                            </JuridicoActionDockListRow>
                                        }
                                    />
                                )}

                            <JuridicoActionDockListRow variants={dockItemVariants}>
                                <JuridicoDueArchiveModal
                                    dueId={activeDue?.id ?? ''}
                                    onArchived={handleDueArchived}
                                    trigger={
                                        <Button
                                        disabled={loadingState !== null || !activeDue?.id}
                                        size="none"
                                        variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                    >
                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-red-100 text-red-600 dark:bg-red-950/60 dark:text-red-400">
                                            <Archive size={16} />
                                        </div>
                                        <div className="text-left">
                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                Arquivar
                                            </p>
                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                Arquiva due, extrato e vínculos em cascata
                                            </p>
                                        </div>
                                        </Button>
                                    }
                                />
                            </JuridicoActionDockListRow>

                            {(statusDiligence ===
                                JuridicoDueDiligenceStatusLabels.REVISAO_VALOR_LOA ||
                                statusDiligence ===
                                JuridicoDueDiligenceStatusLabels.PRE_DUE_CEDENTE ||
                                statusDiligence ===
                                JuridicoDueDiligenceStatusLabels.PRE_DUE_ATIVO ||
                                statusDiligence === JuridicoDueDiligenceStatusLabels.REVISAO_DUE ||
                                statusDiligence ===
                                JuridicoDueDiligenceStatusLabels.EM_ANDAMENTO) && (
                                    <JuridicoActionDockListRow variants={dockItemVariants}>
                                        <JuridicoExigenciaModal
                                            title="Enviar para Repactuação"
                                        description="Você está prestes a enviar o ofício Repactuação."
                                        label="Informe o motivo"
                                        submitFn={(data: JuridicoExigenciaFormData) =>
                                            handleRepactuacao(data)
                                        }
                                        confirmButtonText="Enviar para repactuação"
                                        trigger={
                                            <Button
                                                disabled={loadingState !== null}
                                                size="none"
                                                variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                            >
                                                <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-sky-100 text-sky-600 dark:bg-sky-950/60 dark:text-sky-400">
                                                    {loadingState === 'Repactuação' ? (
                                                        <LoaderCircle
                                                            size={16}
                                                            className="animate-spin"
                                                        />
                                                    ) : (
                                                        <ArrowRightLeft size={16} />
                                                    )}
                                                </div>
                                                <div className="text-left">
                                                    <p className="text-sm font-semibold leading-tight text-foreground">
                                                        Repactuação
                                                    </p>
                                                    <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                        Envia ofício para revisão do comercial
                                                    </p>
                                                </div>
                                                </Button>
                                            }
                                        />
                                    </JuridicoActionDockListRow>
                                )}

                            {statusDiligence ===
                                JuridicoDueDiligenceStatusLabels.REVISAO_VALOR_LOA && (
                                    <JuridicoCommonDialog
                                        title="Mudança de Etapa"
                                        description="Deseja enviar ofício para Pré-Due Ativo?"
                                        phaseAdvance={buildPhaseAdvance(JuridicoDueDiligenceStatus.PRE_DUE_ATIVO)}
                                        confirmButtonFn={() =>
                                            handleUpdateDuePhase(
                                                JuridicoDueDiligenceStatus.PRE_DUE_ATIVO,
                                            )
                                        }
                                        trigger={
                                            <JuridicoActionDockListRow variants={dockItemVariants}>
                                                <Button
                                                    disabled={loadingState !== null}
                                                    size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                        {loadingState ===
                                                            JuridicoDueDiligenceStatus.PRE_DUE_ATIVO ? (
                                                            <LoaderCircle
                                                                size={16}
                                                                className="animate-spin"
                                                            />
                                                        ) : (
                                                            <ArrowRight size={16} />
                                                        )}
                                                    </div>
                                                    <div className="text-left">
                                                        <p className="text-sm font-semibold leading-tight text-foreground">
                                                            Seguir para Pré-Due Ativo
                                                        </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Avança uma etapa do processo
                                                        </p>
                                                    </div>
                                                </Button>
                                            </JuridicoActionDockListRow>
                                        }
                                    />
                                )}

                            {statusDiligence ===
                                ComercialPendenciesStatusLabels.VALIDACAO_PROPOSTA && (
                                    <>
                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja enviar ofício para Due em Andamento?"
                                            phaseAdvance={buildPhaseAdvance(JuridicoDueDiligenceStatus.EM_ANDAMENTO)}
                                            confirmButtonFn={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatus.EM_ANDAMENTO,
                                                )
                                            }
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatus.EM_ANDAMENTO ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <ArrowRight size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Seguir para Due em Andamento
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Avança uma etapa do processo
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />

                                        <JuridicoActionDockListRow variants={dockItemVariants}>
                                            <JuridicoCommonDialog
                                                title="Retroceder Etapa"
                                                description="Deseja voltar para Pré-Due Cedente?"
                                                confirmButtonFn={() =>
                                                    handleUpdateDuePhase(
                                                        JuridicoDueDiligenceStatus.PRE_DUE_CEDENTE,
                                                    )
                                                }
                                                trigger={
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                        variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-amber-100 dark:bg-amber-950/60">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatus.PRE_DUE_CEDENTE ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin text-white"
                                                                />
                                                            ) : (
                                                                <ArrowLeft
                                                                    size={16}
                                                                    className="text-amber-600 dark:text-amber-400"
                                                                />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Voltar para Pré-Due Cedente
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Retrocede uma etapa do processo
                                                            </p>
                                                        </div>
                                                    </Button>
                                                }
                                            />
                                        </JuridicoActionDockListRow>
                                    </>
                                )}

                            {statusDiligence === JuridicoDueDiligenceStatusLabels.PRE_DUE_ATIVO && (
                                <>
                                    <JuridicoActionDockListRow variants={dockItemVariants}>
                                        <JuridicoCommonDialog
                                            title="Retroceder Etapa"
                                            description="Deseja voltar para Revisão de Valor e LOA?"
                                            confirmButtonFn={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatus.REVISAO_VALOR_LOA,
                                                )
                                            }
                                            trigger={
                                                <Button
                                                    disabled={loadingState !== null}
                                                    size="none"
                                                    variant="ghost"
                                                    className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-amber-100 dark:bg-amber-950/60">
                                                        {loadingState ===
                                                            JuridicoDueDiligenceStatus.REVISAO_VALOR_LOA ? (
                                                        <LoaderCircle
                                                            size={16}
                                                            className="animate-spin text-white"
                                                        />
                                                    ) : (
                                                        <ArrowLeft
                                                            size={16}
                                                            className="text-amber-600 dark:text-amber-400"
                                                        />
                                                    )}
                                                </div>
                                                <div className="text-left">
                                                    <p className="text-sm font-semibold leading-tight text-foreground">
                                                        Voltar para Revisão valor/LOA
                                                    </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Retrocede uma etapa do processo
                                                        </p>
                                                    </div>
                                                </Button>
                                            }
                                        />
                                    </JuridicoActionDockListRow>

                                    <JuridicoActionDockListRow variants={dockItemVariants}>
                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja enviar ofício para Pré-Due Cedente?"
