                                                JuridicoDueDiligenceStatusFinalization.EM_LIQUIDACAO,
                                            )
                                        }
                                        trigger={
                                            <JuridicoActionDockListRow variants={dockItemVariants}>
                                                <Button
                                                    disabled={loadingState !== null}
                                                    size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                        {loadingState ===
                                                            JuridicoDueDiligenceStatusFinalization.EM_LIQUIDACAO ? (
                                                            <LoaderCircle
                                                                size={16}
                                                                className="animate-spin"
                                                            />
                                                        ) : (
                                                            <ArrowRight size={16} />
                                                        )}
                                                    </div>
                                                    <div className="text-left">
                                                        <p className="text-sm font-semibold leading-tight text-foreground">
                                                            Enviar para Liquidação
                                                        </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Avança uma etapa do processo
                                                        </p>
                                                    </div>
                                                </Button>
                                            </JuridicoActionDockListRow>
                                        }
                                    />
                                )}

                            {statusDiligence ===
                                JuridicoDueDiligenceStatusFinalizationLabels.APROVADO_COM_RESSALVA && (
                                    <>
                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja enviar ofício para Due em Andamento?"
                                            phaseAdvance={buildPhaseAdvance(JuridicoDueDiligenceStatus.EM_ANDAMENTO)}
                                            confirmButtonFn={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatus.EM_ANDAMENTO,
                                                )
                                            }
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-amber-100 text-amber-600 dark:bg-amber-950/60 dark:text-amber-400">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatus.EM_ANDAMENTO ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <ArrowLeft size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Voltar para Due em Andamento
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Retrocede uma etapa do processo
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />

                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja enviar ofício para Liquidação?"
                                            phaseAdvance={buildPhaseAdvance(
                                                JuridicoDueDiligenceStatusFinalization.EM_LIQUIDACAO,
                                            )}
                                            confirmButtonFn={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatusFinalization.EM_LIQUIDACAO,
                                                )
                                            }
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatusFinalization.EM_LIQUIDACAO ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <ArrowRight size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Enviar para Liquidação
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Avança uma etapa do processo
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />
                                    </>
                                )}

                            {statusDiligence ===
                                JuridicoDueDiligenceStatusFinalizationLabels.EM_CESSAO && (
                                    <>
                                        <JuridicoFinishDiligenceModal
                                            onCancel={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatusFinalization.INSERIR_DADOS_FINANCEIROS,
                                                )
                                            }
                                            onFinish={refetchExtratoData}
                                            closeMenu={closeDockMenu}
                                            dueId={activeDue?.id ?? ''}
                                            dueEsteiraId={activeDue?.esteira}
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatusFinalization.INSERIR_DADOS_FINANCEIROS ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <Check size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Inserir dados financeiros
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Avança uma etapa da diligência
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />
                                    </>
                                )}
                            {statusDiligence ===
                                JuridicoDueDiligenceStatusFinalizationLabels.INSERIR_DADOS_FINANCEIROS && (
                                    <>
                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja concluir o processo de diligência?"
                                            phaseAdvance={buildPhaseAdvance('CONCLUIDO')}
                                            confirmButtonFn={() => handleUpdateDuePhase('CONCLUIDO')}
                                            confirmButtonText="Sim"
                                            cancelButtonText="Não"
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 dark:bg-emerald-950/60 dark:text-emerald-400">
                                                            {loadingState === 'CONCLUIDO' ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <Check size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Concluir Diligência
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Finaliza o processo de Diligência do
                                                                extrato
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />
                                    </>
                                )}

                            {statusDiligence ===
                                JuridicoDueDiligenceStatusFinalizationLabels.EM_LIQUIDACAO && (
                                    <>
                                        <JuridicoCommonDialog
                                            title="Mudança de Etapa"
                                            description="Deseja enviar ofício para Revisão de Due Diligence?"
                                            phaseAdvance={buildPhaseAdvance(JuridicoDueDiligenceStatus.REVISAO_DUE)}
                                            confirmButtonFn={() =>
                                                handleUpdateDuePhase(
                                                    JuridicoDueDiligenceStatus.REVISAO_DUE,
                                                )
                                            }
                                            trigger={
                                                <JuridicoActionDockListRow variants={dockItemVariants}>
                                                    <Button
                                                        disabled={loadingState !== null}
                                                        size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                    >
                                                        <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-amber-100 text-amber-600 dark:bg-amber-950/60 dark:text-amber-400">
                                                            {loadingState ===
                                                                JuridicoDueDiligenceStatus.REVISAO_DUE ? (
                                                                <LoaderCircle
                                                                    size={16}
                                                                    className="animate-spin"
                                                                />
                                                            ) : (
                                                                <ArrowLeft size={16} />
                                                            )}
                                                        </div>
                                                        <div className="text-left">
                                                            <p className="text-sm font-semibold leading-tight text-foreground">
                                                                Voltar para Revisão de Due Diligence
                                                            </p>
                                                            <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                                Envia ofício para processo de revisão de
                                                                Due
                                                            </p>
                                                        </div>
                                                    </Button>
                                                </JuridicoActionDockListRow>
                                            }
                                        />

                                        {/* <JuridicoCommonDialog
                                        title="Enviar para Cessão"
                                        description="Deseja enviar o ofício para o estado de Em Cessão?"
                                        confirmButtonText="Sim, enviar"
                                        confirmButtonFn={() => handleUpdateDuePhase(JuridicoDueDiligenceStatusFinalization.EM_CESSAO)}
                                        cancelButtonText="Cancelar"
                                        trigger={
                                            <JuridicoActionDockListRow variants={dockItemVariants}>
                                                <Button
                                                    disabled={loadingState === JuridicoDueDiligenceStatusFinalization.EM_CESSAO}
                                                    size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-sky-100 text-sky-600 dark:bg-sky-950/60 dark:text-sky-400">
                                                        {loadingState === JuridicoDueDiligenceStatusFinalization.EM_CESSAO ? (
                                                            <LoaderCircle
                                                                size={16}
                                                                className="animate-spin"
                                                            />
                                                        ) : (
                                                            <Calendar size={16} />
                                                        )}
                                                    </div>
                                                    <div className="text-left">
                                                        <p className="text-sm font-semibold leading-tight text-foreground">
                                                            Enviar para Cessão
                                                        </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Envia ofício para estado de cessão
                                                        </p>
                                                    </div>
                                                </Button>
                                            </JuridicoActionDockListRow>
                                        }
                                    /> */}
                                        <JuridicoActionDockListRow variants={dockItemVariants}>
                                            <JuridicoCessionaryModal
                                                extratoId={data.id}
                                                dueId={dueId || activeDue?.id || ''}
                                                dueStatus={dueStatusCode || activeDue?.status}
                                                dueStatusLiquidacao={statusLiquidacao}
                                                requirementsData={requirementsData}
                                                linkedCessionariosList={cessionariosList}
                                                smartblockCessionario={smartblockCessionario}
                                                trigger={
                                                    <Button
                                                    disabled={loadingState !== null}
                                                    size="none"
                                                    variant="ghost"
                                                        className={juridicoActionDockActionButtonClass}
                                                >
                                                    <div className="mr-3 flex size-7 items-center justify-center rounded-full bg-sky-100 text-sky-600 dark:bg-sky-950/60 dark:text-sky-400">
                                                        <Calendar size={16} />
                                                    </div>
                                                    <div className="text-left">
                                                        <p className="text-sm font-semibold leading-tight text-foreground">
                                                            Enviar para Cessão
                                                        </p>
                                                        <p className="text-[12px] leading-relaxed text-muted-foreground">
                                                            Envia ofício para estado de cessão
                                                        </p>
                                                    </div>
                                                </Button>
                                            }
                                        />
                                        </JuridicoActionDockListRow>
                                    </>
                                )}
                                </m.div>
                            </div>
                        </m.div>
                    )}
                </AnimatePresence>
            </m.div>
        </JuridicoActionDock>,
        document.body,
    );
};

export default JuridicoDetailsFloatActionMenu;

