'use client';

import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import {
    ProductDialogContent,
    ProductDialogDescription,
    ProductDialogHeader,
    ProductDialogTitle,
    ProductDialogViewTransition,
    productDialogBodyClass,
    productDialogOpaqueShellClass,
    type ProductDialogViewTransitionHandle,
} from '@/design-system';
import { cn } from '@/lib/utils';
import { ChevronLeft } from 'lucide-react';
import { useRef } from 'react';

import { CreateView } from '@/components/certidoes-padrao/create-view';
import { useCertidoesPadroesQuery } from '@/components/certidoes-padrao/hooks';
import { ListView } from '@/components/certidoes-padrao/list-view';
import {
    CERTIDAO_PADRAO_NESTED_CONTENT_CLASS,
    CERTIDAO_PADRAO_NESTED_OVERLAY_CLASS,
    type CertidaoPadraoTemplate,
    type PadraoCertidaoView,
} from '@/components/certidoes-padrao/types';
import { usePadraoCertidaoDialog } from '@/components/certidoes-padrao/use-padrao-certidao-dialog';

export interface PadroesCertidoesDialogProps {
    open: boolean;
    onClose: () => void;
    /** Optional seed/fallback; live list comes from React Query while open. */
    templates?: CertidaoPadraoTemplate[];
    selectedPadraoId?: number;
    onSelectPadrao: (template: CertidaoPadraoTemplate) => void;
    /** When true, stacks above an already-open product dialog. */
    nested?: boolean;
    onCreated?: (template: CertidaoPadraoTemplate) => void;
    onDeleted?: (id: number) => void;
    initialView?: PadraoCertidaoView;
    /** Prefills "Nome do padrão" on create (e.g. "Padrão Acme Ltda"). */
    defaultTemplateName?: string;
}

export function PadroesCertidoesDialog({
    open,
    onClose,
    templates: templatesProp = [],
    selectedPadraoId,
    onSelectPadrao,
    nested = false,
    onCreated,
    onDeleted,
    initialView = 'list',
    defaultTemplateName,
}: PadroesCertidoesDialogProps) {
    const transitionRef = useRef<ProductDialogViewTransitionHandle>(null);
    const liveTemplatesQuery = useCertidoesPadroesQuery(open);
    const templates = liveTemplatesQuery.data ?? templatesProp;

    const vm = usePadraoCertidaoDialog({
        open,
        onClose,
        transitionRef,
        onCreated,
        onDeleted,
        initialView,
        defaultTemplateName,
    });

    return (
        <Dialog open={open} onOpenChange={vm.handleDialogOpenChange}>
            <ProductDialogContent
                size="xl"
                hideClose={false}
                overlayClassName={nested ? CERTIDAO_PADRAO_NESTED_OVERLAY_CLASS : undefined}
                className={cn(
                    'overflow-hidden p-4',
                    productDialogOpaqueShellClass,
                    nested && CERTIDAO_PADRAO_NESTED_CONTENT_CLASS,
                )}
            >
                <ProductDialogViewTransition
                    ref={transitionRef}
                    viewKey={vm.view}
                    direction={vm.viewDirection}
                    enabled={open}
                    remeasureDeps={[templates, vm.padraoDraft, vm.isEditingTemplate]}
                >
                    <ProductDialogHeader className="flex flex-row items-start gap-2 space-y-0 p-0">
                        {!vm.isList ? (
                            <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="mt-0.5 h-8 w-8 shrink-0 rounded-lg text-muted-foreground hover:text-foreground"
                                onClick={vm.goToList}
                                aria-label="Voltar para lista de padrões"
                            >
                                <ChevronLeft size={18} aria-hidden />
                            </Button>
                        ) : null}
                        <div className="min-w-0 flex-1 space-y-1">
                            <ProductDialogTitle>{vm.dialogTitle}</ProductDialogTitle>
                            <ProductDialogDescription>
                                {vm.dialogDescription}
                            </ProductDialogDescription>
                        </div>
                    </ProductDialogHeader>

                    <div className={cn(productDialogBodyClass, 'px-0')}>
                        {vm.isList ? (
                            <ListView
                                templates={templates}
                                selectedPadraoId={selectedPadraoId}
                                onSelectPadrao={(template) => {
                                    onSelectPadrao(template);
                                    onClose();
                                }}
                                onEditPadrao={vm.handleEditPadrao}
                                onCreateNew={vm.goToCreate}
                            />
                        ) : null}
                    </div>

                    {!vm.isList ? (
                        <CreateView
                            padraoDraft={vm.padraoDraft}
                            onUpdateDraft={vm.handleUpdateDraft}
                            onAddCertidao={vm.handleAddCertidao}
                            onRemoveCertidao={vm.handleRemoveCertidao}
                            onSave={vm.handleSavePadrao}
                            onUpdate={vm.handleUpdatePadrao}
                            onDelete={vm.handleDeletePadrao}
                            isSaving={vm.isCreating}
                            isUpdating={vm.isUpdating}
                            isDeleting={vm.isDeleting}
                            isEditing={vm.isEditingTemplate}
                        />
                    ) : null}
                </ProductDialogViewTransition>
            </ProductDialogContent>
        </Dialog>
    );
}

