'use client';

import { Form } from '@/components/ui/form';
import { m, useReducedMotion } from 'motion/react';
import { useMemo } from 'react';
import { ProcessoFormContainerProps } from '../../../interfaces/processos';
import { ProcessosFormService } from '../../../services/ProcessosFormServices';
import { useViewModelProcessosForm } from '../../../ViewModels/useViewModelProcessosForm';
import { ProcessoFormView } from './ProcessoFormView';

export function ProcessoFormContainer({
    dueId,
    responsavelName,
    processosQueryKey,
    selectedProc,
    mode,
    displayIndex,
    tipoLabels,
    isTerceiro,
    processosContabilizados,
    pessoaId,
    cedenteId,
    onConfirmPrecatorioExclusao,
}: ProcessoFormContainerProps) {
    const prefersReducedMotion = useReducedMotion() === true;
    const processosFormService = useMemo(() => new ProcessosFormService(), []);

    const vm = useViewModelProcessosForm({
        dueId,
        pessoaId,
        processosQueryKey,
        selectedProc,
        processosFormService,
        cedenteId,
        isCedente: !isTerceiro,
        mode,
    });

    const formContentKey = selectedProc.id ?? selectedProc.clientRowKey ?? 'local-draft';

    return (
        <Form {...vm.form}>
            <m.div
                key={formContentKey}
                initial={{
                    opacity: prefersReducedMotion ? 1 : 0,
                    y: prefersReducedMotion ? 0 : 10,
                }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: prefersReducedMotion ? 0 : 0.2 }}
            >
                <ProcessoFormView
                    vm={vm}
                    mode={mode}
                    responsavelName={responsavelName}
                    displayIndex={displayIndex}
                    tipoLabels={tipoLabels}
                    isTerceiro={isTerceiro}
                    processosContabilizados={processosContabilizados}
                    pessoaId={pessoaId}
                    onConfirmPrecatorioExclusao={onConfirmPrecatorioExclusao}
                    selectedProc={selectedProc}
                />
            </m.div>
        </Form>
    );
}

