    brokerData: DueDiligenceBrokerDetails | null;
    isLocked?: boolean;
    /** ID do extrato/ofício (não da due). */
    extratoId: string;
    dueId?: string;
}

export function EnvolvedPartsCards({
    brokerData,
    isLocked = false,
    extratoId,
    dueId,
}: EnvolvedPartsCardsProps) {
    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(extratoId, dueId);

    const cessionarioData = useMemo(() => {
        return linkedCedentesList?.filter(
            (cedente) => cedente.cedente?.tipo_do_cedente === 'CESSIONARIO',
        );
    }, [linkedCedentesList]);

    const cedenteData = useMemo(() => {
        return linkedCedentesList?.filter(
            (cedente) => cedente.cedente?.tipo_do_cedente === 'CEDENTE',
        );
    }, [linkedCedentesList]);

    const coordinatorName = brokerData?.coordenador?.nome?.trim() || 'Não informado';

    return (
        <div className="flex flex-col gap-8">
            <section className="space-y-4">
                <div className="flex items-center gap-2">
                    <Users className="size-4 text-celer-blue" aria-hidden />
                    <h2 className={productDialogSectionHeadingClass}>Partes envolvidas</h2>
                </div>

                <div className="grid grid-cols-1 items-stretch gap-4 md:grid-cols-2 xl:grid-cols-3">
                    {cedenteData?.map((cedente, idx) => (
                        <PartCard
                            key={`cedente-${idx}-${cedente.cedente?.id || idx}`}
                            title="Cedente"
                            icon={User}
                            name={cedente.cedente?.nome}
                            document={cedente.cedente?.documento}
                        />
                    ))}

                    {cessionarioData?.map((cessionario) => (
                        <ExtratoCessionarioManageCard
                            key={`cessionario-${cessionario.id}`}
                            link={cessionario}
                            extratoId={extratoId}
                            dueId={dueId}
                            isLocked={isLocked}
                            layout="finance"
                        />
                    ))}

                    <PartCard
                        title="Broker"
                        icon={Briefcase}
                        name={brokerData?.nome}
                        document={brokerData?.cpf_cnpj}
                    />
                </div>
            </section>

            <section className="space-y-4">
                <div className="flex items-center gap-2">
                    <UserCog className="size-4 text-celer-blue" aria-hidden />
                    <h2 className={productDialogSectionHeadingClass}>Coordenação</h2>
                </div>

                <div className="rounded-2xl border border-border/80 bg-muted/5 p-4 [&_p]:wrap-break-word">
                    <ProductDialogDataField label="Coordenador" value={coordinatorName} />
                </div>
            </section>
        </div>
    );
}

