'use client';

import { CollaborativeSection } from '@/components/Collaboration/CollaborativeSection';
import { useCollaborativeSectionLock } from '@/components/Collaboration/use-collaborative-section-lock';
import { JuridicoCessionaryModal } from '@/components/Modals/Juridico/CessionaryModal/JuridicoCessionaryModal';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { productDialogOutlineButtonClass, productDialogPrimaryButtonClass } from '@/design-system';
import { DUE_REQUIREMENT_SECTION_HIGHLIGHT_CLASS } from '@/functions/juridico/due-requirement-highlight';
import { useOficioLinkedCedentesQuery } from '@/hooks/queries/cedentes';
import { cn } from '@/lib/utils';
import { useJuridicoDetailsStore } from '@/store/useJuridicoDetailsStore';
import type { DueDiligenceDetailed, DueInputErrorTypes, ItensChecklist } from '@/types/due-diligence';
import { Info, UserPlus, UserRound } from 'lucide-react';
import { VinculadoCessionarioManageCard } from './VinculadoCessionarioManageCard';

const CEDENTE_SECTION_ID = 'cedente';

interface JuridicoDetailsInvestidorProps {
    detail: DueDiligenceDetailed | null | undefined;
    extratoId?: string;
    dueId?: string;
    dueStatus?: string;
    requirementsData?: ItensChecklist[];
    isLocked?: boolean;
}

function VincularInvestidorButton({
    extratoId,
    dueId,
    dueStatus,
    requirementsData,
    linkedCessionariosList,
    smartblockCessionario,
    variant = 'default',
}: {
    extratoId: string;
    dueId: string;
    dueStatus?: string;
    requirementsData: ItensChecklist[];
    linkedCessionariosList: ReturnType<typeof useOficioLinkedCedentesQuery>['data'];
    smartblockCessionario?: DueDiligenceDetailed['smartblock_cessionario'];
    variant?: 'default' | 'outline';
}) {
    const cessionarios =
        linkedCessionariosList?.filter((link) => link.cedente?.tipo_do_cedente === 'CESSIONARIO') ??
        [];

    return (
        <JuridicoCessionaryModal
            linkMode="link-only"
            extratoId={extratoId}
            dueId={dueId}
            dueStatus={dueStatus}
            requirementsData={requirementsData}
            linkedCessionariosList={cessionarios}
            smartblockCessionario={smartblockCessionario}
            trigger={
                <Button
                    type="button"
                    variant={variant}
                    size="sm"
                    className={cn(
                        'gap-1.5 shrink-0',
                        variant === 'outline'
                            ? productDialogOutlineButtonClass
                            : productDialogPrimaryButtonClass,
                    )}
                >
                    <UserPlus className="size-3.5" aria-hidden />
                    Vincular investidor
                </Button>
            }
        />
    );
}

export function JuridicoDetailsInvestidor({
    detail,
    extratoId,
    dueId,
    dueStatus,
    requirementsData = [],
    isLocked = false,
}: JuridicoDetailsInvestidorProps) {
    const requiredChecksErrorType = useJuridicoDetailsStore((store) => store.requiredInputsErrorType);
    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(extratoId, dueId);
    const { sectionLock, isLockedByOther } = useCollaborativeSectionLock(CEDENTE_SECTION_ID);

    const vinculados = detail?.cessionarios_vinculados ?? [];

    const totalCount = vinculados.length;

    const isCessionariosRequirementHighlighted = requiredChecksErrorType.includes(
        'Cessionários vinculados ao extrato' as DueInputErrorTypes,
    );

    const canManageLinks = !isLocked && !isLockedByOther && Boolean(extratoId && dueId);

    return (
        <CollaborativeSection
            sectionId={CEDENTE_SECTION_ID}
            lock={sectionLock}
            isLockedByOther={isLockedByOther}
        >
            <Card
                id="due_cessionarios_vinculados"
                className={cn(
                    'rounded-2xl border border-border/80 bg-(--paper-surface) shadow-[0_1px_2px_rgba(15,23,42,0.06)] dark:border-white/10 dark:bg-(--graphite-panel)',
                    isCessionariosRequirementHighlighted && DUE_REQUIREMENT_SECTION_HIGHLIGHT_CLASS,
                )}
            >
                <CardHeader className="flex flex-row items-start justify-between gap-3 border-b border-border/60 px-5 py-4 dark:border-white/10">
                    <div className="flex min-w-0 items-center gap-3">
                        <div
                            className="flex size-9 shrink-0 items-center justify-center rounded-xl border border-border/70 bg-celer-blue/8 text-celer-blue dark:border-white/10"
                            aria-hidden
                        >
                            <UserRound className="size-4" />
                        </div>
                        <div className="min-w-0">
                            <CardTitle className="font-satoshi text-base font-bold tracking-tight">
                                {totalCount > 1 ? 'Investidores vinculados' : 'Investidor vinculado'}
                            </CardTitle>
                            <p className="mt-0.5 text-[13px] text-muted-foreground">
                                {totalCount === 0
                                    ? 'Nenhum investidor nesta operação ainda'
                                    : totalCount === 1
                                      ? '1 investidor nesta operação'
                                      : `${totalCount} investidores nesta operação`}
                            </p>
                        </div>
                    </div>
                    {canManageLinks && totalCount > 0 ? (
                        <VincularInvestidorButton
                            extratoId={extratoId!}
                            dueId={dueId!}
                            dueStatus={dueStatus ?? detail?.status}
                            requirementsData={requirementsData}
                            linkedCessionariosList={linkedCedentesList}
                            smartblockCessionario={detail?.smartblock_cessionario}
                            variant="outline"
                        />
                    ) : null}
                </CardHeader>
                <CardContent className="space-y-4 px-5 py-4">
                    {detail?.smartblock_cessionario?.mensagem ? (
                        <div
                            role="status"
                            className="flex gap-2.5 rounded-xl border border-celer-blue/20 bg-celer-blue/6 px-3.5 py-2.5 text-[13px] leading-snug text-foreground"

