'use client';
import { ResourceCollaborationShell } from '@/components/Collaboration/ResourceCollaborationShell';
import { RepactuacaoV2Banner } from '@/components/Repactuacao/RepactuacaoV2Banner';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { isNexoIntegrationEnabled } from '@/config/environment.config';
import { TOAST_INTERVAL_AWAIT_PROMISE } from '@/constants/constants';
import { QueryKeys } from '@/constants/query-keys';
import {
    ComercialPendenciesStatusLabels,
    JuridicoDueDiligenceStatusLabels,
} from '@/enums/dueDiligence';
import { resolveDueResponsavel } from '@/functions/due-diligence/resolve-due-responsavel';
import { isDueModeloV2 } from '@/functions/juridico/isDueModeloV2';
import { mapDueStatusDisplayForV1Ui } from '@/functions/juridico/mapDueStatusDisplayForV1Ui';
import {
    areAllOficioDuesArchived,
    findActiveDueFromOficioDues,
    findIniciadaRepactuacao,
} from '@/functions/juridico/resolveOficioDueSummary';
import {
    getLiquidacaoCessaoAcceptedStatusLabels,
    verifyOficioVisibility,
} from '@/functions/juridico/verifyOficioVisibility';
import { TOAST_LOADING_ID, sendToastMessage } from '@/functions/messages/toastMessage';
import { resolveOperationalProposta, resolvePropostaLiquidacaoRef } from '@/functions/repactuacao/resolve-proposta-liquidacao-ref';
import { resolveRepactuacaoV2Href } from '@/functions/repactuacao/resolve-repactuacao-v2';
import { sleep } from '@/functions/timer/sleep';
import { cn } from '@/lib/utils';
import { getCurrentProposalData } from '@/services/BrokerServices';
import { fetchDueDiligenceData, fetchDueRequirementsChecks } from '@/services/due-diligence';
import { getOficioDetailsData } from '@/services/oficios';
import { finishRepactuacao } from '@/services/repactuacao';
import { BrokerPropostaDataResults } from '@/types/broker';
import { DueDiligenceDetailed, ItensChecklist } from '@/types/due-diligence';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { AlertCircle, AlertTriangle, ArchiveRestore, CheckCircle, Info, LoaderCircle } from 'lucide-react';
import { usePathname } from 'next/navigation';
import { Suspense, lazy, useMemo, useState } from 'react';
import { AccessErrorCard } from '../Cards/AccessErrorCard';
import { DueModeloMismatchCard } from '../Cards/DueModeloMismatchCard';
import { BrokerExigenciasViewer } from '../CRM/Broker/BrokerExigenciasViewer';
import { ReadOnlyOficioInfoForm } from '../Forms/ReadOnlyOficioInfoForm';
import LifeCycleStep from '../LifeCycleStep';
import { JuridicoDueUnarchiveModal } from '../Modals/Juridico/JuridicoDueUnarchiveModal';
import { ChecklistRequisitosSkeleton } from '../Skeletons/Juridico/ChecklistRequisitosSkeleton';
import { DetailsCedenteInfoSkeleton } from '../Skeletons/Juridico/DetailsCedenteInfoSkeleton';
import JuridicoDetailsSkeleton from '../Skeletons/Juridico/JuridicoDetailsSkeleton';
import { Button } from '../ui/button';
import { CardPagamentoCedentes } from './CardPagamentoCedentes';
import { DueStatusSlaHistoryEntry } from './Details/DueStatusOperationalSummary';
import { JuridicoDetailsFinanceIsertionData } from './Details/finance/JuridicoDetailsFinanceIsertionData';
import { DUE_V1_ACTION_DOCK_CLEARANCE_CLASS } from './Details/juridico-action-dock-styles';
import { JuridicoDetailsBrokerBank } from './Details/JuridicoDetailsBrokerBank';
import JuridicoDetailsCedenteRevision from './Details/JuridicoDetailsCedenteRevision';
import { JuridicoDetailsDueLink } from './Details/JuridicoDetailsDueLink';
import JuridicoDetailsFloatActionMenu from './Details/JuridicoDetailsFloatActionMenu';
import { JuridicoDetailsInvestidor } from './Details/JuridicoDetailsInvestidor';
import { JuridicoDetailsLiquidacaoChecklist } from './Details/JuridicoDetailsLiquidacaoChecklist';
import { JuridicoDetailsLiquidacaoEscritura } from './Details/JuridicoDetailsLiquidacaoEscritura';
import JuridicoDetailsPreDueAtivo from './Details/JuridicoDetailsPreDueAtivo';
import JuridicoDetailsPriceRevision from './Details/JuridicoDetailsPriceRevision';
import JuridicoDetailsVerifyAutenticity from './Details/JuridicoDetailsVerifyAutenticity';
import { JuridicoObservationSection } from './Details/JuridicoObservationSection';
import { OficioFolderComingSoonSection } from './Details/OficioFolder/OficioFolderComingSoonSection';
import { OficioFolderSection } from './Details/OficioFolder/OficioFolderSection';
import { useDueModeloRouteGuard } from './DueDiligence2/hooks/useDueModeloRouteGuard';
import { JuridicoDetailsCedenteInfo } from './JuridicoDetailsCedenteInfo';
import { JuridicoDetailsCredorInfo } from './JuridicoDetailsCredorInfo';
import { JuridicoDetailsInfoProcesso } from './JuridicoDetailsInfoProcesso';
import { JuridicoDetailsInfoValues } from './JuridicoDetailsInfoValues';
import { JuridicoMemoriaCalculoQuickAccess } from './JuridicoMemoriaCalculoQuickAccess';
import { resolveDueDetailErrorType } from './resolveDueDetailErrorType';
const JuridicoDetailsHistory = lazy(() => import('./Details/JuridicoDetailsHistory'));
const BrokerCommentsSectionLazy = lazy(() => import('../CRM/Broker/CommentsSection'));
const TableMovimentacaoProcessualLazy = lazy(
    () => import('../Tables/MovimentacaoProcessual/table'),
);
const ChecklistRequisitosLazy = lazy(() => import('./ChecklistRequisitos'));

export const LegalDetails = ({ id }: { id: string }) => {
    // ================
    // # React Query
    // ================

    // Query para dados detalhados da due
    const { data: dueDiligenceDetailedData, isLoading: isLoadingDueDiligenceDetailed, error: dueDiligenceError } =
        useQuery<DueDiligenceDetailed>({
            queryKey: [QueryKeys.dueDiligence.details, id, 'v1'],
            queryFn: () => fetchDueDiligenceData(id),
            enabled: !!id,
            retry: false,
        });
    const isRedirectingDueModelo = useDueModeloRouteGuard(dueDiligenceDetailedData);

    // Query para dados detalhados do oficio vinculado à due
    const { data: oficioData, isLoading: isLoadingOficio } = useQuery({
        queryKey: [QueryKeys.oficios.item, dueDiligenceDetailedData?.extrato_detail?.id],
        queryFn: () => getOficioDetailsData(dueDiligenceDetailedData?.extrato_detail?.id as string),
        enabled:
            !!dueDiligenceDetailedData?.extrato_detail?.id &&
            !isRedirectingDueModelo,
    });

    // Query para os dados dos requisitos do processo da due
    const { data: checkRequirementsData, isLoading: isLoadingRequirements } = useQuery<
        ItensChecklist[]
    >({
        queryKey: [QueryKeys.dueDiligence.dueRequirementsChecks, dueDiligenceDetailedData?.id],
        queryFn: () => fetchDueRequirementsChecks(dueDiligenceDetailedData?.id as string),
        enabled: !!dueDiligenceDetailedData?.id && !isRedirectingDueModelo,
    });

    const operationalProposalForDue = resolveOperationalProposta(
        oficioData?.propostas,
        dueDiligenceDetailedData?.proposta_origem,
    );

    // Query para os dados da proposta operacional (vigente ou proposta_origem da due em repactuação)
    const { data: vigenteProposalData } = useQuery<BrokerPropostaDataResults>({
        queryKey: [QueryKeys.propostas.vigente, oficioData?.id, operationalProposalForDue?.uuid],
        queryFn: () => getCurrentProposalData(operationalProposalForDue!.uuid),
        enabled: !!operationalProposalForDue?.uuid,
    });

    // ==================
    // # State - Cedente Ativo
    // ==================

    // ==================
    // # Constants
    // ==================
    const queryClient = useQueryClient();
    const [pendingExigenciasCount, setPendingExigenciasCount] = useState(0);
    const currentPath = usePathname() ?? '';
    const activeDue = findActiveDueFromOficioDues(oficioData?.due_diligence);
    const statusDiligenceCode =
        dueDiligenceDetailedData?.status || activeDue?.status || '';
    const statusLiquidacao =
        dueDiligenceDetailedData?.status_liquidacao ?? null;
    /** Rótulo normalizado para UI v1 (V2 `Liquidação` → `Em Liquidação` via status_liq). */
    const statusDiligence = mapDueStatusDisplayForV1Ui({
        statusCode: statusDiligenceCode,
        statusDisplay:
            dueDiligenceDetailedData?.status_display || activeDue?.status_display || '',
        statusLiquidacao,
    });
    const extratoStatus = oficioData?.status || '';
    const hasConcludedDiligence =
        oficioData?.due_diligence?.some((due) => due.status === 'CONCLUIDO') ?? false;

